    INSERT INTO public.topics (name, icon, category) VALUES ('Unit 02: Thinking & Learning', '🎓', 'Destination C1-C2') RETURNING id INTO v_topic_id;
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'assess (v)', '/əˈses/', 'Đánh giá', 'to make a judgement about the nature or quality of somebody/something', 'Topic Vocabulary', 1, 1),
    (v_topic_id, 'assume (v)', '/əˈsjuːm/', 'Giả sử', 'to think or accept that something is true but without having proof of it.', 'Topic Vocabulary', 1, 2),
    (v_topic_id, 'baffle (v)', '/ˈbæfl/', 'Làm rối lên, làm cho ai đó bối rối, khó hiểu', 'to confuse somebody completely; to be too difficult or strange for somebody to understand or explain.', 'Topic Vocabulary', 1, 3),
    (v_topic_id, 'biased (adj)', '/ˈbaɪəst/', 'Thiên kiến, thành kiến', 'tending to show favour towards or against one group of people or one opinion for personal reasons; making unfair judgements e.g: biased information/sources/press reports', 'Topic Vocabulary', 1, 4),
    (v_topic_id, 'concentrate (v)', '/ˈkɒnsntreɪt/', 'Tập trung', 'to give all your attention to something and not think about anything else (ON)', 'Topic Vocabulary', 1, 5),
    (v_topic_id, 'consider (v)', '/kənˈsɪdə(r)/', 'Xem xét, cân nhắc', 'to think about something carefully, especially in order to make a decision', 'Topic Vocabulary', 1, 6),
    (v_topic_id, 'contemplate (v)', '/ˈkɒntəmpleɪt/', 'Xem xét, cân nhắc ( 1 thời gian dài)', 'to think about whether you should do something, or how you should do something SYNONYM: consider, think about/of', 'Topic Vocabulary', 1, 7),
    (v_topic_id, 'cynical (adj)', '/ˈsɪnɪkl/', 'hoài nghi, nghi ngờ', 'believing that people only do things to help themselves rather than for good or honest reasons - cynical (about something) not believing that something good will happen or that something is important', 'Topic Vocabulary', 1, 8),
    (v_topic_id, 'deduce (v)', '/dɪˈdjuːs/', 'suy ra, suy luận', '( from sth): to form an opinion about something based on the information or evidence that is available SYNONYM: infer', 'Topic Vocabulary', 1, 9),
    (v_topic_id, 'deliberate (adj)', '/dɪˈlɪbərət/', 'cố tình, cố ý', 'one on purpose rather than by accident SYNONYM: intentional, planned', 'Topic Vocabulary', 1, 10),
    (v_topic_id, 'dilemma (n)', '/dɪˈlemə/', 'tình huống tiến thoái, lưỡng nan', 'situation that makes problems, often one in which you have to make a very difficult choice between things of equal importance', 'Topic Vocabulary', 1, 11),
    (v_topic_id, 'discriminate (v)', '/dɪˈskrɪmɪneɪt/', 'phân biệt, đối xử không công bằng', 'to treat one person or group worse/better than another in an unfair way', 'Topic Vocabulary', 1, 12),
    (v_topic_id, 'dubious (adj)', '/ˈdjuːbiəs/', 'nghi ngờ về điều gì', '= doubtful ( about sth)// suspicious', 'Topic Vocabulary', 1, 13),
    (v_topic_id, 'estimate (v) (n)', '/ˈestɪmeɪt/', 'ước tính - sự ước tính', 'to form an idea of the cost, size, value etc. of something, but without calculating it exactly', 'Topic Vocabulary', 1, 14),
    (v_topic_id, 'faith (n)', '/feɪθ/', 'sự tin tưởng (IN)', 'trust in somebody’s ability or knowledge; trust that somebody/something will do what has been promised', 'Topic Vocabulary', 1, 15),
    (v_topic_id, 'gather (v)', '/ˈɡæðə(r)/', 'tụ tập, tập hợp', 'to come together, or bring people together, in one place to form a group', 'Topic Vocabulary', 1, 16),
    (v_topic_id, 'genius (n)', '/ˈdʒiːniəs/', 'thiên tài, thần đồng', 'a person who is unusually intelligent or artistic, or who has a very high level of skill, especially in one area', 'Topic Vocabulary', 1, 17),
    (v_topic_id, 'grasp (v)', '/ɡrɑːsp/', 'cầm, nắm', 'grasp somebody/something to take a strong hold of somebody/something SYNONYM: grip', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'guesswork (n)', '/ˈɡeswɜːk/', 'quá trình dự đoán, sự dự đoán', 'the process of trying to find an answer by guessing when you do not have enough information to be sure', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'hunch (n)', '/ hʌntʃ/', 'dự cảm, cảm giác', 'a feeling that something is true even though you do not have any evidence to prove it', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'ideology (n)', '/ˌaɪdiˈɒlədʒi/', 'hệ tư tưởng', 'a set of ideas that an economic or political system is based on', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'ingenious (adj)', '/ɪnˈdʒiːniəs/', 'thông minh, khéo léo, xuất chúng', '(of a person) very intelligent and skilful, or (of a thing) skilfully made or planned and involving new ideas and methods.', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'inspiration (n)', '/ˌɪnspəˈreɪʃn/', 'người, vật, sự việc tạo cảm hứng', 'a person or thing that is the reason why somebody creates or does something', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'intuition (n)', '/ˌɪntjuˈɪʃn/', 'trực giác, cảm giác', 'the ability to know something by using your feelings rather than considering the facts', 'Topic Vocabulary', 1, 24),
    (v_topic_id, 'justify (v)', '/ˈdʒʌstɪfaɪ/', 'biện hộ, biện minh, bào chữa', 'to show that somebody/something is right or reasonable', 'Topic Vocabulary', 1, 25),
    (v_topic_id, 'naive (v)', '/naɪˈiːv/', 'ngây thơ, đơn giản', 'innocent and simple ( behaviour) - not having enough knowledge, good judgement or experience of life and too willing to believe that people always tell you the truth', 'Topic Vocabulary', 1, 26),
    (v_topic_id, 'notion (n)', '/ˈnəʊʃn/', 'ý tưởng, ý kiến, khái niệm', 'an idea, a belief or an understanding of something', 'Topic Vocabulary', 1, 27),
    (v_topic_id, 'optimistic (adj)', '/ˌɒptɪˈmɪstɪk/', 'lạc quan', 'expecting good things to happen or something to be successful; showing this feeling', 'Topic Vocabulary', 1, 28),
    (v_topic_id, 'paradox (n)', '/ˈper.ə.dɑːks/', 'nghịch lý', 'a situation or statement that seems impossible or is difficult to understand because it contains two opposite facts or characteristics', 'Topic Vocabulary', 1, 29),
    (v_topic_id, 'pessimistic (adj)', '/ˌpesɪˈmɪstɪk/', 'bi quan', 'expecting bad things to happen or something not to be successful; showing this', 'Topic Vocabulary', 1, 30),
    (v_topic_id, 'plausible (adj)', '/ˈplɔːzəbl/', 'hợp lí, khả thi, đúng', 'reasonable and likely to be true', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'ponder (v)', '/ˈpɒndə(r)/', 'xem xét, cân nhắc', 'to think about something carefully for a period of time SYNONYM: consider', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'prejudiced (adj)', '/ˈpredʒ.ə.dɪst/', 'thành kiến', 'showing an unreasonable dislike for something or someone:', 'Topic Vocabulary', 1, 33),
    (v_topic_id, 'presume (v)', '/prɪˈzjuːm/', 'giả sử, cho rằng ( cái gì đó đúng dù không có bằng chứng)', 'to suppose that something is true, although you do not have actual proof SYNONYM : assume', 'Topic Vocabulary', 1, 34),
    (v_topic_id, 'query (v, n)', '/ˈkwɪəri/', 'câu hỏi, thẩm vấn, sự nghi vấn - hỏi, nghi vấn, thẩm vấn', 'a question, especially one asking for information or expressing a doubt about something - to ask a question; to put a question to somebody', 'Topic Vocabulary', 1, 35),
    (v_topic_id, 'reckon (v)', '/ˈrekən/', 'suy nghĩ, tin rằng, cho rằng ( that) ( informal)', 'to think something or have an opinion about something', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'reflect (v)', '/rɪˈflekt/', 'suy ngẫm, suy nghĩ kĩ', 'to think carefully and deeply about something', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'sceptical', '/ skeptical (adj) /', 'nghi ngờ về cái gì', 'having doubts that a claim or statement is true or that something will happen', 'Topic Vocabulary', 1, 38),
    (v_topic_id, 'speculate (v)', '/ˈspekjuleɪt/', 'nghiên cứu, suy xét', 'to form an opinion about something without knowing all the details or facts ( on, upon)', 'Topic Vocabulary', 1, 39),
    (v_topic_id, 'suppose (v)', '/səˈpəʊz/', 'giả sử', 'to think or believe that something is true or possible (based on the knowledge that you have)', 'Topic Vocabulary', 1, 40),
    (v_topic_id, 'academic (adj, n)', '/ˌækəˈdemɪk/', 'thuộc về giáo dục, học thuật - giảng viên', '[usually before noun] connected with education, especially studying in schools and universities - a person who teaches and/or does research at a university or college', 'Topic Vocabulary', 1, 41),
    (v_topic_id, 'conscientious (adj)', '/ˌkɒnʃiˈenʃəs/', 'chu đáo, cẩn thận, tỉ mỉ, tận tâm', 'taking care to do things carefully and correctly', 'Topic Vocabulary', 1, 42),
    (v_topic_id, 'cram (v)', '/kræm/', 'học nhồi nhét', 'cram (for something) (North American English, informal or British English, old-fashioned) to learn a lot of things in a short time, in preparation for an exam SYNONYM: swot', 'Topic Vocabulary', 1, 43),
    (v_topic_id, 'curriculum (n)', '/kəˈrɪkjələm/', 'chương trình học', 'the subjects that are included in a course of study or taught in a school, college, etc.', 'Topic Vocabulary', 1, 44),
    (v_topic_id, 'distance learning (n)', '/ˌdɪstəns ˈlɜːnɪŋ/', 'học từ xa', 'a system of education in which people study at home with the help of special internet sites and send or email work to their teachers', 'Topic Vocabulary', 1, 45),
    (v_topic_id, 'graduate (v), (n)', '/ˈɡrædʒueɪt/', 'tốt nghiệp - người tốt nghiệp', 'to get a degree, especially your first degree, from a university or college - a person who has a university degree', 'Topic Vocabulary', 1, 46),
    (v_topic_id, 'ignorant (adj)', '/ˈɪɡnərənt/', 'không được ăn học, giáo dục, ngu dốt', 'not having or showing much knowledge or information about things; not educated', 'Topic Vocabulary', 1, 47),
    (v_topic_id, 'inattentive (adj)', '/ˌɪnəˈtentɪv/', 'không chú ý', 'not paying attention to something/somebody', 'Topic Vocabulary', 1, 48),
    (v_topic_id, 'intellectual (adj)', '/ˌɪntəˈlektʃuəl/', 'thuộc về đầu óc, trí tuệ', 'connected with or using a person’s ability to think in a logical way and understand things SYNONYM: mental', 'Topic Vocabulary', 1, 49),
    (v_topic_id, 'intelligent (adj) ɪnˈtelɪdʒənt/', NULL, 'thông minh', 'good at learning, understanding and thinking in a logical way about things; showing this ability', 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'intensive (adj)', '/ɪnˈtensɪv/', 'tập trung', 'involving a lot of work or activity done in a short time', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'knowledgeable (adj)', '/ˈnɒlɪdʒəbl/', 'có hiểu biết, có kiến thức', 'knowing a lot SYNONYM: well- informed', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'lecture (v, n)', '/ˈlektʃə(r)/', 'giảng bài - bài giảng', 'to give a talk or a series of talks to a group of people on a subject, especially as a way of teaching in a university or college - a talk that is given to a group of people to teach them about a particular subject,', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'mock exam (n)', '/mɒk /', 'thi thử', 'an examination, esp in a school, taken as practice before an official examination', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'plagiarise (v)', '/ˈpleɪdʒəraɪz/', 'đạo văn', 'to copy another person’s ideas, words or work and pretend that they are your own', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'self-study (n)', '/ˌself ˈstʌdi/', 'tự học', 'the activity of learning about something without a teacher to help you', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'seminar (n)', '/ˈsemɪnɑː(r)/', 'hội thảo', 'a class at a university or college when a small group of students and a teacher discuss or study a particular topic - a meeting for discussion or training', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'special needs (np)', '/ˌspeʃ.əl ˈniːdz/', 'nhu cầu đặc biệt', 'the particular things needed by or provided to help people who have an illness or condition that makes it difficult for them to do the things that other people do', 'Topic Vocabulary', 1, 58),
    (v_topic_id, 'tuition (n)', '/tjuˈɪʃn/', 'tiền học phí', 'the money that you pay to be taught, especially in a college or university', 'Topic Vocabulary', 1, 59),
    (v_topic_id, 'tutorial (n)', '/tjuːˈtɔːriəl/', 'gia sư, sách hướng dẫn', 'a period of teaching in a university that involves discussion between an individual student or a small group of students and a tutor', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'brush up (on)', NULL, 'cải thiện, ôn lại, ôn tập', 'to improve your knowledge of something already learned but partly forgotten:', 'Phrasal Verbs', 2, 61),
    (v_topic_id, 'come a(round) to', NULL, 'thay đổi quan điểm, ý định ( vì bị ảnh hưởng bởi quan điểm của người khác', 'to change your opinion of something, often influenced by another person''s opinion.', 'Phrasal Verbs', 2, 62),
    (v_topic_id, 'come up with', NULL, 'nghĩ ra ( ý kiến, kế hoạch)', 'to suggest or think of an idea or plan', 'Phrasal Verbs', 2, 63),
    (v_topic_id, 'face up to', NULL, 'chấp nhận, đối mặt', 'to accept that a difficult situation exists', 'Phrasal Verbs', 2, 64),
    (v_topic_id, 'figure out', NULL, 'hiểu, giải quyết cái gì', 'to understand or solve something', 'Phrasal Verbs', 2, 65),
    (v_topic_id, 'hit upon', NULL, 'bất chợ nghĩ ra', 'to think of an idea when you didn''t expect or intend to, especially one that solves a problem', 'Phrasal Verbs', 2, 66),
    (v_topic_id, 'make out', NULL, 'thấy, nghe, hiểu / đề nghị/ ám chỉ', 'see, hear or understand s.o or sth with difficulties/ suggest/ imply', 'Phrasal Verbs', 2, 67),
    (v_topic_id, 'mull over', NULL, 'xem xét kĩ, cân nhắc', 'to spend time thinking carefully about a plan or proposal SYNONYM: consider', 'Phrasal Verbs', 2, 68),
    (v_topic_id, 'piece together', NULL, 'hiểu được, biết được ( bằng cách gom, tổng hợp dữ liệu)', 'to understand a story, situation, etc. by taking all the facts and details about it and putting them together', 'Phrasal Verbs', 2, 69),
    (v_topic_id, 'puzzle out', NULL, 'tìm ra câu trả lời', 'to find the answer to a difficult or confusing problem by thinking carefully SYNONYM: work out', 'Phrasal Verbs', 2, 70),
    (v_topic_id, 'read up ( on/ about)', NULL, 'đọc nhiều ( về 1 chủ đề)', 'to read a lot about a subject', 'Phrasal Verbs', 2, 71),
    (v_topic_id, 'swot up (on)', NULL, 'nghiên cứu, ôn kĩ', 'to study a particular subject very hard, especially in order to prepare for an exam', 'Phrasal Verbs', 2, 72),
    (v_topic_id, 'take in', NULL, 'hiểu, nhớ cái gì vừa nghe, đọc - lừa ai - cho ai ở nhờ', 'to understand or remember something that you hear or read - to make somebody believe something that is not true - to allow somebody to stay in your home', 'Phrasal Verbs', 2, 73),
    (v_topic_id, 'think over', NULL, 'xem xét kĩ trước quyết định', 'to consider something carefully, especially before reaching a decision', 'Phrasal Verbs', 2, 74),
    (v_topic_id, 'think through', NULL, 'xem xét kĩ', 'to consider a problem or a possible course of action fully', 'Phrasal Verbs', 2, 75),
    (v_topic_id, 'think up', NULL, 'bịa, tưởng tượng', 'invent or imagine sth, especially an excuse', 'Phrasal Verbs', 2, 76),
    (v_topic_id, 'go to your head', NULL, 'nghĩ rằng, ảo tưởng rằng mình quan trọng hơn người khác', 'If something goes to someone''s head, it makes that person think that they are very important and makes them a less pleasant person', 'Idioms', 4, 77),
    (v_topic_id, 'have/ keep your wits about you', NULL, 'có thể suy nghĩ nhanh và đưa ra quyết định hợp lí', 'be able to think quickly and make sensible decisions', 'Idioms', 4, 78),
    (v_topic_id, 'in the dark (about)', NULL, 'không biết cái gì (vì người khác giấu bạn)', 'not knowing much about sth because other people keep it secret from you', 'Idioms', 4, 79),
    (v_topic_id, 'know what''s what', NULL, 'biết rõ, hiểu rõ', 'If you know what''s what, you have a lot of experience and can judge people and situations well', 'Idioms', 4, 80),
    (v_topic_id, 'not have a leg to stand on', NULL, 'không có cách nào chứng minh rằng bạn đúng.', 'to be in a situation in which you cannot prove something:', 'Idioms', 4, 81),
    (v_topic_id, 'Not see the wood for the trees', NULL, 'không nhìn thấy đại cuộc vì quá chú trọng tiểu tiết.', 'to be unable to get a general understanding of a situation because you are too worried about the details', 'Idioms', 4, 82),
    (v_topic_id, 'Put two and two together', NULL, 'đoán được sự thật dựa vào điều mh thấy và nghe.', 'to guess the truth about a situation from what you have seen or heard.', 'Idioms', 4, 83),
    (v_topic_id, 'Quick/ slow on the uptake', NULL, 'hiểu vấn đề nhanh/ khó khăn', 'If someone is quick/slow on the uptake, they understand things easily/with difficulty', 'Idioms', 4, 84),
    (v_topic_id, 'Ring a bell', NULL, 'nhớ mang máng', 'to sound familiar', 'Idioms', 4, 85),
    (v_topic_id, 'Round the bend', NULL, 'trở nên điên khùng, không thể hành động đúng đắn.', 'mentally confused or unable to act in a reasonable way// to become crazy', 'Idioms', 4, 86),
    (v_topic_id, 'Split hairs', NULL, 'tranh luận về những điều nhỏ nhặt', 'to argue about small details of something', 'Idioms', 4, 87),
    (v_topic_id, 'Take stock (of)', NULL, 'suy nghĩ kĩ, xem xét kĩ, cân nhắc', 'to think carefully about a situation or event and form an opinion about it, so that you can decide what to do.', 'Idioms', 4, 88),
    (v_topic_id, 'To say the least', NULL, 'ít nhất', 'used to show that something is worse or more serious than you are actually saying', 'Idioms', 4, 89),
    (v_topic_id, 'strike a balance', NULL, 'giữ thế cân bằng', 'to achieve a state in which different things occur in equal or proper amounts or have an equal or proper amount of importance', 'Phrases & Collocations', 3, 90),
    (v_topic_id, 'upset the balance - redress the balance - change/alter/s hift the balance', NULL, 'mất sự cân bằng - thay đổi tình huống để lấy lại cân bằng - thay đổi, chuyển hướng sự cân bằng', '=make it less equal or correct - to change a situation in order to make things fair and equal', 'Phrases & Collocations', 3, 91),
    (v_topic_id, 'balance between/ of', NULL, 'sự cân bằng giữa/ của', NULL, 'Phrases & Collocations', 3, 92),
    (v_topic_id, 'on balance', NULL, 'sau khi cân nhắc, xem xét 2 mặt của 1 vấn đề.', 'after considering the power or influence of both sides of a question', 'Phrases & Collocations', 3, 93),
    (v_topic_id, 'off balance', NULL, 'mất thăng bằng', 'likely to fall or be knocked down:', 'Phrases & Collocations', 3, 94),
    (v_topic_id, 'basis for', NULL, 'nền tảng cho…', 'the most important facts, ideas, etc. from which something is developed', 'Phrases & Collocations', 3, 95),
    (v_topic_id, 'on a daily/ temporary basis', NULL, 'hàng ngày/ tạm thời', NULL, 'Phrases & Collocations', 3, 96),
    (v_topic_id, 'on the basis of', NULL, 'dựa vào, bởi vì ( cái gì)', 'because of a particular fact or situation', 'Phrases & Collocations', 3, 97),
    (v_topic_id, 'express belief(s)', NULL, 'diễn tả niềm tin', NULL, 'Phrases & Collocations', 3, 98),
    (v_topic_id, 'belief in', NULL, 'niềm tin vào cái gì', 'a strong feeling that something/somebody exists or is true; confidence that something/somebody is good or right', 'Phrases & Collocations', 3, 99),
    (v_topic_id, 'contrary to popular belief', NULL, 'trái với suy nghĩ/ quan điểm thông thường', 'used to say that something is true even though people believe the opposite', 'Phrases & Collocations', 3, 100);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'beyond belief', NULL, 'ngoài sức tưởng tượng, khó tin', 'extremely surprising or unreasonable, so that you cannot believe it', 'Phrases & Collocations', 3, 101),
    (v_topic_id, 'in the belief that', NULL, 'với niềm tin rằng', 'believing that', 'Phrases & Collocations', 3, 102),
    (v_topic_id, 'popular/ widely held/ widespread/ strong/ growing belief', NULL, 'niềm tin phổ biến, vững chắc, ngày càng được củng cố', NULL, 'Phrases & Collocations', 3, 103),
    (v_topic_id, 'pick one''s brain', NULL, 'hỏi xin lời khuyên của ai về chủ đề mà họ biết rõ.', 'to ask someone''s advice about a subject the person knows a lot about', 'Phrases & Collocations', 3, 104),
    (v_topic_id, 'rack your brain', NULL, 'nghĩ kĩ, nghĩ nát óc', 'to think very hard', 'Phrases & Collocations', 3, 105),
    (v_topic_id, 'the brains behind', NULL, 'người đứng sau', 'the person responsible for inventing, developing, or organizing something', 'Phrases & Collocations', 3, 106),
    (v_topic_id, 'brainless', NULL, 'ngu ngốc', 'stupid', 'Phrases & Collocations', 3, 107),
    (v_topic_id, 'brainchild (of)', NULL, 'ý tưởng, phát minh của ai', 'an idea or invention of one person or a small group of people', 'Phrases & Collocations', 3, 108),
    (v_topic_id, 'brainstorm', NULL, 'động não, nghĩ ra', 'to all think about something at the same time, often in order to solve a problem or to create good ideas', 'Phrases & Collocations', 3, 109),
    (v_topic_id, 'brainwash', NULL, 'tẩy não', 'to force somebody to accept your ideas or beliefs, for example by repeating the same thing many times or by preventing the person from thinking clearly', 'Phrases & Collocations', 3, 110),
