    (v_topic_id, 'influence (v, n)', '/ˈɪnfluəns/', 'làm ảnh hưởng - sự ảnh hưởng', 'to affect or alter by indirect or intangible means - the effect that somebody/something has on the way a person thinks or behaves or on the way that something works or develops', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'innovation (n)', '/ˌɪnəˈveɪʃn/', 'sự đổi mới, cải tiến', 'the introduction of new things, ideas or ways of doing something', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'innovative (adj)', '/ˈɪnəveɪtɪv/', 'đổi mới, cải tiến', 'introducing or using new ideas, ways of doing something, etc.', 'Topic Vocabulary', 1, 38),
    (v_topic_id, '- to continue being good or suitable', NULL, 'bền, kéo dài', NULL, 'Topic Vocabulary', 1, 39),
    (v_topic_id, '- to express firmly your belief that something is true', NULL, 'duy trì , giữ vững', NULL, 'Topic Vocabulary', 1, 40),
    (v_topic_id, '- to become more developed mentally and emotionally and behave in a responsible way - mentally and emotionally well-developed, and therefore responsible', NULL, 'trưởng thành - chín chắn, trưởng thành', NULL, 'Topic Vocabulary', 1, 41),
    (v_topic_id, '- to change something such as a plan, opinion, law, or way of behaviour slightly, usually to improve it or make it more acceptable', NULL, 'sửa đổi ( để dễ được chấp nhận)', NULL, 'Topic Vocabulary', 1, 42),
    (v_topic_id, '- new and not resembling something formerly known or used', NULL, 'mới lạ', NULL, 'Topic Vocabulary', 1, 43),
    (v_topic_id, '- to continue to do something despite difficulties or opposition, in a way that can seem unreasonable', NULL, 'kiên trì, khăn khăn (IN)', NULL, 'Topic Vocabulary', 1, 44),
    (v_topic_id, '23.potential (n, adj) /pəˈtenʃl/', NULL, 'Tiềm năng - có tiềm năng', 'something that can develop or become', 'Topic Vocabulary', 1, 45),
    (v_topic_id, '- to develop to a higher, better, or more advanced stage - a forward or onward movement (as to an objective or to a goal); advance', NULL, 'tiến triển - Sự tiến triển', NULL, 'Topic Vocabulary', 1, 46),
    (v_topic_id, '- relating to the most basic and important parts of something; complete and detailed', NULL, 'căn nguyên, toàn bộ', NULL, 'Topic Vocabulary', 1, 47),
    (v_topic_id, '- to make a substance pure by taking other substances out of it', NULL, 'lọc', NULL, 'Topic Vocabulary', 1, 48),
    (v_topic_id, '- change that is made to a social system, an organization, etc. in order to improve or correct it - an improvement, especially in a person''s behaviour or in the structure of something', NULL, 'cải cách - sự cải cách', NULL, 'Topic Vocabulary', 1, 49),
    (v_topic_id, '- to continue to exist when other parts or other things no longer exist', NULL, 'sống sót, còn lại', NULL, 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, '- to look at or consider again an idea, piece of writing, etc. in order to correct or improve it', NULL, 'xem lại, sửa lại, duyệt lại, ôn lại', NULL, 'Topic Vocabulary', 1, 51),
    (v_topic_id, '- an attempt, by a large number of people, to change the government of a country, especially by violent action', NULL, 'Cuộc cách mạng', NULL, 'Topic Vocabulary', 1, 52),
    (v_topic_id, '- to exchange for or replace by another - a period of time worked by a group of workers who start work as another group finishes', NULL, 'đổi chỗ, chuyển giao, sự thay đổi ca làm việc', NULL, 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'spoil (v)', '/spɔɪl/', 'chiều hư, làm hư hỏng', 'to allow a child to do or have everything that it wants to, usually so that it expects to get everything it wants and does not show respect to other people', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'status quo (n phr)', '/ˌsteɪtəs ˈkwəʊ/', 'hiện trạng', 'the situation as it is now, or as it was before a recent change', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'steady (v, adj)', '/ˈstedi/', 'làm cho vững chắc - ổn định', 'to make something stop shaking or moving - happening in a smooth, gradual, and regular way, not suddenly or unexpectedly', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'substitute (v, n)', '/ˈsʌbstɪtjuːt/', 'thay thế - người, vật thay thế', 'to use something or someone instead of another thing or person - a person or thing that you use or have instead of the one you normally use or have', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'sustain (v)', '/səˈsteɪn/', 'tiếp sức, duy trì', 'to provide enough of what somebody/something needs in order to live or exist - to cause or allow something to continue for a period of time', 'Topic Vocabulary', 1, 58),
    (v_topic_id, 'switch (v, n)', '/swɪtʃ/', 'thay đổi - công tắc', 'to change or make something change from one thing to another - a device that controls an electric current and turns it on or off', 'Topic Vocabulary', 1, 59),
    (v_topic_id, 'transform (v)', '/trænsˈfɔːm/', 'biến đổi', 'to change the form of something; to change in form', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'trend (n)', '/trend/', 'xu hướng', 'a general development or change in a situation or in the way that people are behaving', 'Topic Vocabulary', 1, 61),
    (v_topic_id, 'uniform (adj)', '/ˈjuːnɪfɔːm/', 'đồng dạng, cùng kiểu, đồng phục', 'the same; not changing or different in any way', 'Topic Vocabulary', 1, 62),
    (v_topic_id, 'breakthrough (n)', '/ˈbreɪkθruː/', 'đột phá', 'an important discovery or event that helps to improve a situation or provide an answer to a problem', 'Topic Vocabulary', 1, 63),
    (v_topic_id, 'broadband (adj, n)', '/ˈbrɔːdbænd/', 'băng thông rộng', 'capable of carrying sound, pictures and video that are sent at high speeds - a way of connecting to the internet that allows you to receive information, including pictures, etc., very quickly and that is always active (so that the user does not have to connect each time)', 'Topic Vocabulary', 1, 64),
    (v_topic_id, 'click (v)', '/klɪk/', 'kêu lẻng xẻng, nhấp (chuột máy tính)', 'to make a short, sharp sound, or to make something do this', 'Topic Vocabulary', 1, 65),
    (v_topic_id, 'complex (adj)', '/ˈkɒmpleks/', 'phức tạp', 'made of many different things or parts that are connected; difficult to understand', 'Topic Vocabulary', 1, 66),
    (v_topic_id, 'consumer electronics (n phr)', '/kənˌsjuːmər ɪˌlekˈtrɒnɪks/', 'điện tử dân dụng', 'electronic devices such as televisions, computers and smartphones bought by individual customers rather than by businesses', 'Topic Vocabulary', 1, 67),
    (v_topic_id, 'craft (v, n)', '/krɑːft/', 'làm thủ công ( bằng tay) - thủ công', 'to make objects, especially in a skilled way - an activity involving a special skill at making things with your hands', 'Topic Vocabulary', 1, 68),
    (v_topic_id, 'data (n)', '/ˈdeɪtə/', 'dữ liệu', 'facts or information, especially when examined and used to find out things or to make decisions', 'Topic Vocabulary', 1, 69),
    (v_topic_id, 'download (v, n)', NULL, 'tải xuống - bản tải xuống', 'to copy or move programs or information into a computer''s memory, especially from the internet or a larger computer, or to be moved in this way - a computer program or information that has been or can be copied into a computer''s memory', 'Topic Vocabulary', 1, 70),
    (v_topic_id, 'file (n)', '/faɪl/', 'tập tin - cái giũa', 'a collection of information stored together in a computer, under a particular name - a thin, flat or rounded metal tool with rough surfaces for rubbing wooden or metal objects to make them smooth or to change their shape', 'Topic Vocabulary', 1, 71),
    (v_topic_id, '(games) console ( n phr)', '/kənˈsəʊl/', 'trò chơi điều khiển', 'a console game is a form of video game, consisting of manipulable images (and usually sounds) generated by a video game console and displayed on a television or similar audio-video system', 'Topic Vocabulary', 1, 72),
    (v_topic_id, 'manual ( adj, n)', '/ˈmænjuəl/', 'làm bằng tay - cẩm nang', 'involving using the hands or physical strength - a book that gives you practical instructions on how to do something or how to use something, such as a machine', 'Topic Vocabulary', 1, 73),
    (v_topic_id, 'network (v, n)', '/ˈnetwɜːk/', 'nối mạng - mạng lưới', 'to connect computers together so that they can share information - a group formed from parts that are connected together', 'Topic Vocabulary', 1, 74),
    (v_topic_id, 'nuclear (adj)', '/ˈnuːkliər/', '(thuộc) hạt nhân', 'using, producing or resulting from nuclear energy', 'Topic Vocabulary', 1, 75),
    (v_topic_id, 'offline (adj,adv)', '/ˌɔːfˈlaɪn/', 'ngoại tuyến', 'using a computer, but not connected to the Internet - not directly controlled by or connected to a computer or to the internet', 'Topic Vocabulary', 1, 76),
    (v_topic_id, 'online (adj,adv)', '/ˌɒnˈlaɪn/', 'trực tuyến', 'on the internet - available on or done using the internet or other computer network', 'Topic Vocabulary', 1, 77),
    (v_topic_id, 'primitive ( adj)', '/ˈprɪmətɪv/', 'nguyên thủy', 'belonging to a simple way of life that existed in the past and does not have modern industries and machines', 'Topic Vocabulary', 1, 78),
    (v_topic_id, 'programmer (n)', '/ˈprəʊɡræmə(r)/', 'lập trình viên', 'a person whose job is writing computer programs', 'Topic Vocabulary', 1, 79),
    (v_topic_id, 'resource (n)', '/rɪˈsɔːs/', 'nguồn', 'something that gives help, support etc when needed; a supply; a means', 'Topic Vocabulary', 1, 80),
    (v_topic_id, 'technique (n)', '/tekˈniːk/', 'kỹ thuật, chuyên môn', 'a particular way of doing something, especially one in which you have to learn special skills', 'Topic Vocabulary', 1, 81),
    (v_topic_id, 'upload (v)', '/ˌʌpˈləʊd/', 'tải lên', 'to transfer programs or data from a smaller computer system (= a client) to a larger one (= a host), especially over the Internet', 'Topic Vocabulary', 1, 82),
    (v_topic_id, 'back up', NULL, 'yểm trợ, hỗ trợ - sao chép, sao lưu', 'to give support to someone by telling other people that you agree with them - make a copy of information on your computer', 'Topic Vocabulary', 1, 83),
    (v_topic_id, 'change around', NULL, 'thay đổi ( xung quanh)', 'to move things so that they are in different places or positions', 'Topic Vocabulary', 1, 84),
    (v_topic_id, 'change into', NULL, 'biến đổi thành', 'to stop being in one state, condition, or form and start being in another, or to make something do this', 'Topic Vocabulary', 1, 85),
    (v_topic_id, 'change out of', NULL, 'thay ( đồ, trang phục…)', 'To remove an item of clothing in order to put on a different one', 'Topic Vocabulary', 1, 86),
    (v_topic_id, 'do away with', NULL, 'loại bỏ (cái gì đó)', 'to stop or eliminate something', 'Topic Vocabulary', 1, 87),
    (v_topic_id, 'do up', NULL, 'sửa chữa, sơn, cải thiện…', 'repair, paint and improve an old building, car, boat, etc; fasten ( an item of clothing)', 'Topic Vocabulary', 1, 88),
    (v_topic_id, 'fade away', NULL, 'nhạt dần, mờ dần, bieén mất dần', 'disappear slowly', 'Topic Vocabulary', 1, 89),
    (v_topic_id, 'key in', NULL, 'nhập thông tin, dữ liệu bằng bàn phím', 'to put information into a computer or a machine using a keyboard', 'Topic Vocabulary', 1, 90),
    (v_topic_id, 'make into', NULL, 'biến thứ gì đó thành thứ khác', 'to change something into something else', 'Topic Vocabulary', 1, 91),
    (v_topic_id, 'mix up', NULL, 'gây ra nhầm lẫn', 'a mistake that causes confusion. - to think that one person or thing is another person or thing', 'Topic Vocabulary', 1, 92),
    (v_topic_id, 'switch on/off', NULL, 'bật/ tắt công tắc ( máy móc,..)', 'to turn a light, machine, etc. (off/on by pressing a button or switch', 'Topic Vocabulary', 1, 93),
    (v_topic_id, 'take apart', NULL, 'tháo ra, tách ra ( thành nhiều mảnh )', 'to separate something into all its different parts', 'Topic Vocabulary', 1, 94),
