    (v_topic_id, 'a leopard can''t/doesn''t change its spots', NULL, 'bản chất khó thay đổi, (tương tự câu giang sơn dễ đổi, bản tính khó rời)', 'something you say that means a person''s character, especially if it is bad, will not change, even if they pretend that it will', 'Topic Vocabulary', 1, 99),
    (v_topic_id, 'all mod cons', NULL, 'những ( thiết bị trong gia đình) tiện nghi và hiện đại', 'the modern facilities in a house that make it easy and pleasant to live in.', 'Topic Vocabulary', 1, 100);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'break the mould', NULL, 'phá vỡ khuôn mẫu', 'to do something differently after it has been done in the same way for a long time', 'Topic Vocabulary', 1, 101),
    (v_topic_id, 'change your tune', NULL, 'đổi ý kiến, thái độ hoặc hành động về điều gì đó cụ thể', 'to start saying something different about a subject or situation, or to start behaving in a different way', 'Topic Vocabulary', 1, 102),
    (v_topic_id, 'a change of heart', NULL, 'sự thay đổi trong quan điểm và cảm xúc trước một vấn đề.', 'if you have a change of heart, you change your opinion or feelings about something.', 'Topic Vocabulary', 1, 103),
    (v_topic_id, 'know sth inside out', NULL, 'biết ngọn ngành, hiểu tường tận về vấn đề gì đó', 'to know everything about something', 'Topic Vocabulary', 1, 104),
    (v_topic_id, 'reinvent the wheel', NULL, 'phí thời gian tạo ra cái gì đã tồn tại và vận hành tốt trước đó.', 'waste time creating something that already exists and works well', 'Topic Vocabulary', 1, 105),
    (v_topic_id, 'stick to your guns', NULL, 'giữ vững quan điểm, kiên định lập trường', 'to continue to have your beliefs or continue with a plan of action, even if other people disagree with you', 'Topic Vocabulary', 1, 106),
    (v_topic_id, 'a tool of the trade', NULL, 'những công cụ, kỹ năng cho một công việc cụ thể.', 'the skills and equipment that you need in order to do your job', 'Topic Vocabulary', 1, 107),
    (v_topic_id, 'turn over a new leaf', NULL, 'thay đổi theo chiều hướng tốt lên, tích cực hơn', 'to start behaving in a better way', 'Topic Vocabulary', 1, 108),
    (v_topic_id, '(have/gain/provide ) access to', NULL, 'được quền xâm nhập vào', 'get permission to go to a place', 'Phrases & Collocations', 3, 109),
    (v_topic_id, 'internet access', NULL, 'truy cập Internet', 'access to the internet for a computer or other device', 'Phrases & Collocations', 3, 110),
    (v_topic_id, 'wheelchair access', NULL, 'lối đi dành riêng cho xe lăn', 'a method by which someone can enter or leave a place in a wheelchair', 'Phrases & Collocations', 3, 111),
    (v_topic_id, 'break a habit', NULL, 'loại bỏ thói quen xấu', 'to stop doing something that is a habit, especially something bad or harmful', 'Phrases & Collocations', 3, 112),
    (v_topic_id, 'break with tradition', NULL, 'phá vỡ truyền thống', 'To do something in a new, different, or unique way.', 'Phrases & Collocations', 3, 113),
    (v_topic_id, 'make the break (from)', NULL, 'chấm dứt (quan hệ, công việc...)', 'To run away from someone or stop doing something)', 'Phrases & Collocations', 3, 114),
    (v_topic_id, 'take/ have/ need a break', NULL, 'nghỉ một lát, nghỉ ngơi', 'to stop doing something for a short period of time : to rest', 'Phrases & Collocations', 3, 115),
    (v_topic_id, 'a welcome break from', NULL, 'được mong đợi, chào mừng', 'a pleasant surprise', 'Phrases & Collocations', 3, 116),
    (v_topic_id, 'lunch/tea/coffee break', NULL, 'nghỉ ngữa giờ làm việc để ăn uống nhẹ, bữa trà chiều', 'a short pause from work in the middle of the morning or afternoon for a drink, a rest etc', 'Phrases & Collocations', 3, 117),
    (v_topic_id, 'change from sth to', NULL, 'chyển từ cái gì sang cái khác', 'to change or be different according to the person, situation, time etc involved', 'Phrases & Collocations', 3, 118),
    (v_topic_id, '.change sth into', NULL, 'trở thành, biến đổi thành', 'to stop being in one state, condition, or form and start being in another, or to make something do this', 'Phrases & Collocations', 3, 119),
    (v_topic_id, 'change sth for', NULL, 'đổi cái gì sang cái gì khác/ đổi cái gì cho ai đó', 'transform one thing into another / make a difference to someone', 'Phrases & Collocations', 3, 120),
    (v_topic_id, 'change for the better/worse', NULL, 'thay đổi tiến bộ lên - thay đổi tệ đi, lạc hậu đi', 'an improvement in situation or state of affairs over what was - a worsening of a situation or state of affairs from what was', 'Phrases & Collocations', 3, 121),
    (v_topic_id, 'change your mind', NULL, 'đổi ý', 'to change your decision, plan, or opinion about something', 'Phrases & Collocations', 3, 122),
    (v_topic_id, 'change the subject', NULL, 'đổi chủ đề, đánh trống lảng', 'to start talking about something different', 'Phrases & Collocations', 3, 123),
    (v_topic_id, 'make a change', NULL, 'thay đổi, sửa đổi tốt hơn bình thường', 'used for saying that something is different from and better than usual', 'Phrases & Collocations', 3, 124),
    (v_topic_id, 'undergo a change', NULL, 'trải qua sự thay đổi', 'to go through a change', 'Phrases & Collocations', 3, 125),
    (v_topic_id, 'set a clock', NULL, 'ấn định thời gian, (cài đặt trong đồng hồ)', 'to change the time on a clock to a later time', 'Phrases & Collocations', 3, 126),
    (v_topic_id, 'watch the clock', NULL, 'nhìn thời gian trôi', 'to keep looking at the time on a clock or a watch because you are bored or you want something to end', 'Phrases & Collocations', 3, 127),
    (v_topic_id, 'against the clock', NULL, 'chạy đua với thời gian', 'If you do something against the clock, you do it as fast as possible and try to finish it before a certain time', 'Phrases & Collocations', 3, 128),
    (v_topic_id, 'around the clock', NULL, 'làm việc gì đó cả ngày không ngừng nghỉ', 'all day and all night without stopping', 'Phrases & Collocations', 3, 129),
    (v_topic_id, 'clockwise', NULL, 'theo chiều kim đồng hồ.', '(moving around) in the same direction as the pointers of a clock or watch', 'Phrases & Collocations', 3, 130),
    (v_topic_id, 'clockwork', NULL, 'bộ máy đồng hồ - đều đặn, máy móc như một cái máy; như bộ máy đồng hồ', 'a system of springs and wheels that you wind (= turn) with a key or handle to make some clocks, toys, and other devices operate - Something that is like clockwork runs easily, automatically, and always in the same way', 'Phrases & Collocations', 3, 131),
    (v_topic_id, 'date from', NULL, 'xuất hiện, ra đời từ một thời điểm cụ thể', 'to have been made in or to have come into being in (a certain time in the past)', 'Phrases & Collocations', 3, 132),
    (v_topic_id, 'date back to', NULL, 'đã có, tồn tại từ (xưa, lâu)', 'to have existed for a particular length of time or since a particular time', 'Phrases & Collocations', 3, 133),
    (v_topic_id, 'keep (sth) up to date', NULL, 'cập nhật cái gì đó phiên bản mới nhất', 'To ensure something is the most current version available. (Often used in reference to technology.)', 'Phrases & Collocations', 3, 134),
    (v_topic_id, 'set/fix a date', NULL, 'đặt ngày hẹn, quyết định ngày hẹn', 'to agree on a date (a time and place for a meeting)', 'Phrases & Collocations', 3, 135),
    (v_topic_id, 'go on / make a date (with sb)', NULL, 'hẹn hò', 'to arrange to meet someone on a particular day', 'Phrases & Collocations', 3, 136),
    (v_topic_id, 'at a later/future date', NULL, 'vào một ngày nào đó trong tương lai', 'at some time in the future', 'Phrases & Collocations', 3, 137),
    (v_topic_id, 'to date', NULL, 'cho tới nay', 'up to now', 'Phrases & Collocations', 3, 138),
    (v_topic_id, 'demand sth from sb', NULL, 'yêu cầu một cái gì đó từ một ai đó', 'to insist that someone do, provide, or relinquish something.', 'Phrases & Collocations', 3, 139),
    (v_topic_id, 'meet/satisfy a demand', NULL, 'đáp ứng nhu cầu', 'to do something that someone wants, needs, or expects you to do or be as good as they need, expect etc', 'Phrases & Collocations', 3, 140),
    (v_topic_id, 'make demand', NULL, 'đòi hỏi, yêu sách', 'If someone or something makes demands on you, they require you to do things which need a lot of time, energy, or money', 'Phrases & Collocations', 3, 141),
    (v_topic_id, 'the demand for', NULL, 'yêu cầu, nhu cầu về', 'in need of', 'Phrases & Collocations', 3, 142),
    (v_topic_id, 'in demand', NULL, 'được chuộng', 'to be wanted by a lot of people', 'Phrases & Collocations', 3, 143),
    (v_topic_id, 'on demand', NULL, 'theo yêu cầu.', 'at any time that someone wants or needs something - involved in or relating to providing services when a customer wants or asks for them', 'Phrases & Collocations', 3, 144),
    (v_topic_id, 'have/lack the energy to do', NULL, 'không còn đủ năng lượng để làm gì', 'not having enough energy to do', 'Phrases & Collocations', 3, 145),
    (v_topic_id, 'put/throw your energy into', NULL, 'dồn sức vào việc gì', 'to start doing an activity with a lot of effort and energy', 'Phrases & Collocations', 3, 146),
    (v_topic_id, 'nuclear energy', NULL, 'năng lượng hạt nhân', 'energy released by reactions within atomic nuclei, as in nuclear fission or fusion.', 'Phrases & Collocations', 3, 147),
    (v_topic_id, 'source of energy', NULL, 'nguồn năng lượng', 'A source of usable energy that may be collected or recovered', 'Phrases & Collocations', 3, 148),
    (v_topic_id, 'energy needs', NULL, 'nhu cầu năng lượng', 'the amount of food energy needed to balance energy expenditure in order to maintain body size, body composition and a level of necessary and desirable physical activity consistent with long-term good health', 'Phrases & Collocations', 3, 149),
    (v_topic_id, 'energy crisis', NULL, 'khủng hoảng năng lượng', 'a lack of energy or a break in the supply of energy', 'Phrases & Collocations', 3, 150);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'form an impression of', NULL, 'nhận định, hình thành một ấn tượng về', 'to use available information to develop or reach an opinion or idea', 'Phrases & Collocations', 3, 151),
    (v_topic_id, 'take/assume the form of', NULL, 'được cho là, giả định là hình thức, giả dạng hình dạng của người/vật nào đó', 'assume sth/sb has the shape of sb/st else', 'Phrases & Collocations', 3, 152),
    (v_topic_id, 'fill in/out a form', NULL, 'điền vào một biểu mẫu', 'to give written information, esp. by completing a form - to fill in the form is to supply information as required and to fill out the form is to complete it', 'Phrases & Collocations', 3, 153),
    (v_topic_id, 'in the form of', NULL, 'dưới hình thức', 'having the shape, character, style etc of', 'Phrases & Collocations', 3, 154),
    (v_topic_id, 'in good/bad form', NULL, 'sung sức; vui vẻ - cư xử không đúng', 'if you say that someone is in good form, you mean that they seem healthy and cheerful - It is in a bad form if the behaviors or actions that are considered socially inappropriate, distasteful, or rude', 'Phrases & Collocations', 3, 155),
    (v_topic_id, 'application form', NULL, 'mẫu đăng ký; mẫu đơn xin việc', 'a form to be filled in when applying for job, grant etc', 'Phrases & Collocations', 3, 156),
    (v_topic_id, 'good (for sb) to do', NULL, 'điều nên làm, tốt cho ai để làm gì', 'shoud do something to bring good things', 'Phrases & Collocations', 3, 157),
    (v_topic_id, 'a good deal', NULL, 'nhiều - một thoả thuận tốt', 'a lot - a good agreement', 'Phrases & Collocations', 3, 158),
    (v_topic_id, 'a good many/few', NULL, 'nhiều', 'a fairly large number of things or people', 'Phrases & Collocations', 3, 159),
    (v_topic_id, 'good of sb to do', NULL, 'đánh giá tốt hành vi của ai đó', 'judging someone''s behaviour good', 'Phrases & Collocations', 3, 160),
    (v_topic_id, 'for sb''s own good', NULL, 'vì lợi ích của chính ai đó', 'being or done for the benefit of oneself', 'Phrases & Collocations', 3, 161),
    (v_topic_id, 'no good', NULL, 'không đàng hoàng, tử tế', 'morally bad', 'Phrases & Collocations', 3, 162),
    (v_topic_id, 'it''s no good doing', NULL, 'chẳng có ích lợi gì, vô ích', 'used to say that an action will not achieve what it is intended to achieve', 'Phrases & Collocations', 3, 163),
    (v_topic_id, 'know (sth) about', NULL, 'biết, hiểu rõ về gì đó', 'to be knowledgeable about, familiar with, or skilled at something', 'Phrases & Collocations', 3, 164),
    (v_topic_id, 'know sb/sth to be/do', NULL, 'biết điều gì xảy ra - biết ai đó làm gì - biết ai đó là ai', 'if something or someone is known to be or do something, people know that it is true or happens, or that someone is or does something', 'Phrases & Collocations', 3, 165),
    (v_topic_id, 'know better', NULL, 'biết rõ hơn - làm gì tốt hơn', 'to know or understand more than other people - to be smart or sensible enough not to do something', 'Phrases & Collocations', 3, 166),
    (v_topic_id, 'get/come to know', NULL, 'làm quen', 'to start to be familiar with someone or something', 'Phrases & Collocations', 3, 167),
    (v_topic_id, 'let sb know', NULL, 'cho ai biết điều gì đó', 'to tell someone something', 'Phrases & Collocations', 3, 168),
    (v_topic_id, 'in the know', NULL, 'am tường, biết rõ', 'if you are in the know about something, especially something that is not known about or understood by many people, you have information about it', 'Phrases & Collocations', 3, 169),
    (v_topic_id, 'know-how', NULL, 'bí quyết', 'knowledge, practical ability, or skill to do something', 'Phrases & Collocations', 3, 170),
    (v_topic_id, 'lead sb into', NULL, 'dẫn vào cái gì hoặc nơi nào đó', 'to guide or direct someone or something into something or some place. In this usage, a noun or pronoun is usually used between "lead" and "into."', 'Phrases & Collocations', 3, 171),
    (v_topic_id, 'lead the way', NULL, 'dẫn lối - dẫn đầu', 'to be the first person to go somewhere - to be the best', 'Phrases & Collocations', 3, 172),
    (v_topic_id, 'lead the world', NULL, 'đứng đầu thế giới', 'to be better than all other people or things', 'Phrases & Collocations', 3, 173),
    (v_topic_id, 'lead sb to do', NULL, 'khiến ai đó làm gì', 'to cause or compel force one to do something.', 'Phrases & Collocations', 3, 174),
    (v_topic_id, 'lead to/down/through', NULL, 'dẫn đến - dẫn dắt, đánh lừa - đi ngang qua, vượt qua', 'to begin a process that causes something to happen - to deceive (someone) - go through, pass through', 'Phrases & Collocations', 3, 175),
    (v_topic_id, 'take/hold the lead', NULL, 'giữ vị trí dẫn đầu', 'to be in the winning position in a race or competition', 'Phrases & Collocations', 3, 176),
    (v_topic_id, 'follow sb''s lead', NULL, 'làm theo ai đó', 'to do the same thing that someone else has done', 'Phrases & Collocations', 3, 177),
    (v_topic_id, 'in the lead', NULL, 'dẫn đầu - dẫn trước', 'in a position that is ahead of others - leading or ahead in a competition', 'Phrases & Collocations', 3, 178),
    (v_topic_id, 'link to', NULL, 'liên kết với, có mối liên kết với ai, cái gì', 'to have a connection with someone or something', 'Phrases & Collocations', 3, 179),
    (v_topic_id, 'link sth/sb to/with', NULL, 'liên hệ, liên kết với', 'to create or establish a connection between one person or thing and someone or something else. In this usage, a noun or pronoun is used', 'Phrases & Collocations', 3, 180),
    (v_topic_id, 'click on/follow a link', NULL, 'nhấp chuột vào một đường dẫn liên kết', 'if you click on a link, it takes you to a website, social media post, video, etc. on the internet', 'Phrases & Collocations', 3, 181),
    (v_topic_id, '(find/prove/establish) a link between', NULL, 'tìm ra, thiết lập mối liên hệ', 'to find or establish a relationship between two things or situations', 'Phrases & Collocations', 3, 182),
    (v_topic_id, 'change/swap places with', NULL, 'đổi chỗ', 'to take someone’s position while they take yours', 'Phrases & Collocations', 3, 183),
    (v_topic_id, 'take the place of', NULL, 'thay thế', 'to replace (someone or something)', 'Phrases & Collocations', 3, 184),
    (v_topic_id, 'take sb''s place', NULL, 'thế chân, thế chỗ', 'If one thing or person takes the place of another or takes another''s place, they replace the other thing or person', 'Phrases & Collocations', 3, 185),
    (v_topic_id, 'put sth in(to) place', NULL, 'áp dụng, thiết lập, đưa ra điều gì đó', 'to implement (a new policy), to establish', 'Phrases & Collocations', 3, 186),
    (v_topic_id, 'in place of', NULL, 'thay vì', 'instead of someone or something else', 'Phrases & Collocations', 3, 187),
    (v_topic_id, 'out of place', NULL, 'lạc lõng - không đúng chỗ', 'if someone feels out of place or is out of place, they feel uncomfortable in a particular situation or place, or they do not belong there - not in the correct place', 'Phrases & Collocations', 3, 188),
    (v_topic_id, 'place of work', NULL, 'chỗ làm việc', 'the area where you work / have your business / live', 'Phrases & Collocations', 3, 189),
    (v_topic_id, 'no place for', NULL, 'không phải chỗ cho người/ vật nào đó', 'used to say that someone or something does not belong in a particular place, situation, etc', 'Phrases & Collocations', 3, 190),
    (v_topic_id, 'the process of', NULL, 'tiến trình, quy trình', 'a series of actions that you take in order to achieve a result .', 'Phrases & Collocations', 3, 191),
    (v_topic_id, 'in the process of doing', NULL, 'đang thực hiện một nhiệm vụ nào đó', 'If you are in the process of doing something, you have started to do it and are still doing it.', 'Phrases & Collocations', 3, 192),
    (v_topic_id, 'peace process', NULL, 'tiến trình hoà bình', 'a series of discussions to try to find a peaceful solution to a war or to political violence', 'Phrases & Collocations', 3, 193),
    (v_topic_id, 'a process of elimination', NULL, 'quá trình loại trừ, loại bỏ', 'the act of considering and rejecting each possible choice until only one is left', 'Phrases & Collocations', 3, 194),
    (v_topic_id, 'serve a purpose', NULL, 'đáp ứng, phù hợp nhu cầu cần thiết.', 'To fit or satisfy the necessary requirements; to be useful for or fit to achieve some aim, goal, or purpose', 'Phrases & Collocations', 3, 195),
    (v_topic_id, 'the purpose of doing', NULL, 'mục đích của việc làm gì', 'When you do something with purpose, you do it with determination. When your activities have a purpose, you have an aim or intention in mind', 'Phrases & Collocations', 3, 196),
    (v_topic_id, 'sb''s purpose in doing', NULL, 'mục tiêu, mục đích của ai đó khi làm việc làm gì', 'a person''s motivation for accomplishing anything', 'Phrases & Collocations', 3, 197),
    (v_topic_id, 'a sense of purpose', NULL, 'mục đích', 'the quality of having a definite purpose', 'Phrases & Collocations', 3, 198),
    (v_topic_id, 'on purpose', NULL, 'cố ý', 'if you do something on purpose, you do it intentionally', 'Phrases & Collocations', 3, 199),
    (v_topic_id, 'escape from reality', NULL, 'trốn tránh thực tại', 'a defensive reaction involving the use of fantasy as a means of avoiding conflicts and problems of daily living', 'Phrases & Collocations', 3, 200);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'face (up to) reality', NULL, 'đối diện với thực tế', 'to deal directly with (something unwanted or unpleasant) in the actual world', 'Phrases & Collocations', 3, 201),
    (v_topic_id, 'become a reality', NULL, 'trở thành hiện thực', 'You say that something has become a reality when it actually exists or is actually happening', 'Phrases & Collocations', 3, 202),
    (v_topic_id, 'in reality', NULL, 'trên thực tế', 'used for saying that the true situation is different from what has been said or thought', 'Phrases & Collocations', 3, 203),
    (v_topic_id, 'virtual reality', NULL, 'thực tế ảo', 'the use of computer technology to create a simulated environment', 'Phrases & Collocations', 3, 204),
    (v_topic_id, 'reality TV', NULL, 'truyền hình thực tế', 'television programmes about ordinary people who are filmed in real situations, rather than actors', 'Phrases & Collocations', 3, 205),
    (v_topic_id, 'a tool for (doing)', NULL, 'một công cụ để làm việc gì đó', 'a device for accomplishing a task', 'Phrases & Collocations', 3, 206),
    (v_topic_id, 'a tool of', NULL, 'một công cụ', 'something you need to use to do your job', 'Phrases & Collocations', 3, 207),
    (v_topic_id, 'toolbar', NULL, 'thanh công cụ', 'on a computer screen, a row of icons (= small pictures that you choose in order to make the computer do something)', 'Phrases & Collocations', 3, 208),
    (v_topic_id, 'tool kit', NULL, 'bộ dụng cụ', 'a set of tools that are used for making or repairing something', 'Phrases & Collocations', 3, 209),
    (v_topic_id, 'tool box', NULL, 'hộp đồ nghề', 'a container in which you keep and carry small tools, especially those used in the house or for repairing a car', 'Phrases & Collocations', 3, 210),
    (v_topic_id, 'use sth for (doing)', NULL, 'dùng cái gì để làm gì', 'to put something to use for a certain purpose', 'Phrases & Collocations', 3, 211),
    (v_topic_id, 'use sth to do', NULL, 'dùng cái gì để làm gì', 'to make use of something for a certain purpose', 'Phrases & Collocations', 3, 212),
    (v_topic_id, 'use sth as', NULL, 'dùng cái gì đó như là', 'to make use of a thing''s function as if it were a thing', 'Phrases & Collocations', 3, 213),
    (v_topic_id, 'use sth properly', NULL, 'dùng đúng cách', 'if something is used properly , it is used in a correct and satisfactory way', 'Phrases & Collocations', 3, 214),
    (v_topic_id, 'have many uses', NULL, 'có nhiều công dụng, lợi ích', 'be useful in many situations or ways', 'Phrases & Collocations', 3, 215),
    (v_topic_id, 'in use', NULL, 'được sử dụng', 'being used', 'Phrases & Collocations', 3, 216),
    (v_topic_id, 'of (no) use', NULL, 'không có ích lợi gì', 'to be useless', 'Phrases & Collocations', 3, 217),
    (v_topic_id, 'it''s/there''s no use doing', NULL, 'làm gì đó vô ích', 'the thing someone tries cannot be or was not successful', 'Phrases & Collocations', 3, 218),
    (v_topic_id, 'what''s the use of doing?', NULL, 'có ích gi?/ có tác dụng gì?/ tại sao phải làm (việc gì đó)', 'what reason is there (to do something); why should I bother (doing something)?', 'Phrases & Collocations', 3, 219),
    (v_topic_id, 'surf the Web', NULL, 'lướt mạng', 'To navigate through the World Wide Web or Internet, usually by clicking with a mouse. The term also has a generic meaning of spending time on the Internet.', 'Phrases & Collocations', 3, 220),
    (v_topic_id, 'on the Web', NULL, 'trên mạng', 'on a system for finding information on the internet, in which documents are connected to other documents', 'Phrases & Collocations', 3, 221),
    (v_topic_id, 'website', NULL, 'trang mạng, trang web', 'a place on the Internet with one or more pages of information about a subject', 'Phrases & Collocations', 3, 222),
    (v_topic_id, 'web page', NULL, 'trang mạng, trang web', 'a page of information on the internet about a particular subject, that forms part of a website', 'Phrases & Collocations', 3, 223),
    (v_topic_id, 'webcam', NULL, 'thiết bị ghi hình kỹ thuật số được kết nối với máy vi tính', 'a camera that records moving pictures and sound, and allows these to be broadcast on the internet as they happen', 'Phrases & Collocations', 3, 224),
    (v_topic_id, 'webmaster', NULL, 'người quản trị web(trang mạng)', 'someone whose job is to manage a website', 'Phrases & Collocations', 3, 225),
    (v_topic_id, 'weblog (blog)', NULL, 'nhật ký trực tuyến', 'A website that allows users to reflect, share opinions, and discuss various topics in the form of an online journal while readers may comment on posts', 'Phrases & Collocations', 3, 226),
    (v_topic_id, 'take the wheel', NULL, 'Kiểm soát/quản lý cái gì - cầm lái', 'To take or assume control (of something) - start to drive a car, replacing somebody else', 'Phrases & Collocations', 3, 227),
    (v_topic_id, 'at/behind the wheel', NULL, 'phụ trách, lãnh đạo - lái (phương tiện giao thông)', 'by extension, in charge; acting the leader (of something) - driving a vehicle (and thus literally sitting behind the steering wheel)', 'Word Formation', 5, 228),
    (v_topic_id, 'on wheels', NULL, 'di chuyển trên phương tiện có bánh xe - trơn tru, trôi chảy', 'Literally, on or via a vehicle with wheels, such as an automobile, bicycle, or motorcycle - Very smoothly; without difficulty, problems, or hindrances', 'Word Formation', 5, 229),
    (v_topic_id, 'wheel of fortune', NULL, 'vòng quay may mắn/ bánh xe số phận; sự may mắn, bước ngoặt cuộc đời.', 'used for referring to the fact that situations can change very quickly from good to bad or from bad to good', 'Word Formation', 5, 230),
