    (v_topic_id, 'adjustable', '/ə''dʒʌstəbl/', '(adj) có thể hiệu chỉnh, có thể điều chỉnh', NULL, 'Word Formation', 5, 238),
    (v_topic_id, 'alter', '/''ɔ:ltər/', '(v) thay đổi, đổi', NULL, 'Word Formation', 5, 239),
