    (v_topic_id, 'anew', '/ə''nju:/', '(adv) lại, một lần nữa; lại nữa; bằng cách khác', NULL, 'Word Formation', 5, 272),
    (v_topic_id, 'persist', '/pə''sist/', '(v) bền bỉ, cố chấp', NULL, 'Word Formation', 5, 273),
    (v_topic_id, 'persistence', '/pə''sistəns/', '(n) sự kiên trì, sự bền bỉ', NULL, 'Word Formation', 5, 274),
    (v_topic_id, 'persistently', '/pə''sistəntli/', '(adv) [một cách] kiên trì, [một cách] bền bỉ', NULL, 'Word Formation', 5, 275),
    (v_topic_id, 'place', '/pleis/', '(n) nơi, chỗ, địa điểm (v) để, đặt, đưa vào làm, xếp hạng, đầu tư (vốn)', NULL, 'Word Formation', 5, 276),
