    INSERT INTO public.topics (name, icon, category) VALUES ('Unit 06: Time & Work', '🎓', 'Destination C1-C2') RETURNING id INTO v_topic_id;
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'Abrupt (adj)', '/əˈbrʌpt/', 'Đột ngột, bất ngờ', 'sudden and unexpected, often in an unpleasant way', 'Topic Vocabulary', 1, 1),
    (v_topic_id, 'Anachronism (n)', '/əˈnækrənɪzəm/', 'người, phong tục, ý tưởng lỗi thời', 'a person, a custom or an idea that seems old-fashioned and does not belong to the present', 'Topic Vocabulary', 1, 2),
    (v_topic_id, 'Annual (adj)', '/ˈænjuəl/', 'Hàng năm', 'happening or done once every year', 'Topic Vocabulary', 1, 3),
    (v_topic_id, 'Antique (adj, n)', '/ænˈtiːk/', 'Cổ xưa - Đồ cổ', 'old and often valuable - an object such as a piece of furniture that is old and often valuable', 'Topic Vocabulary', 1, 4),
    (v_topic_id, 'Century (n)', '/ˈsentʃəri/', 'Thế kỷ', 'a period of 100 years', 'Topic Vocabulary', 1, 5),
    (v_topic_id, 'Chronological (adj)', '/ˌkrɒnəˈlɒdʒɪkl/', 'Thuộc niên đại', 'arranged in the order in which they happened', 'Topic Vocabulary', 1, 6),
    (v_topic_id, 'Contemporary (n, adj)', '/kənˈtemprəri/', 'Người đương thời - Đương thời', 'a person who lives or lived at the same time as somebody else, especially somebody who is about the same age - belonging to the same time', 'Topic Vocabulary', 1, 7),
    (v_topic_id, 'Decade (n)', '/ˈdekeɪd/', 'Thập kỷ', 'a period of ten years, especially a continuous period, such as 1910–1919 or 2000–2009', 'Topic Vocabulary', 1, 8),
    (v_topic_id, 'Duration (n)', '/djuˈreɪʃn/', 'Khoảng thời gian', 'the length of time that something lasts or continues', 'Topic Vocabulary', 1, 9),
    (v_topic_id, 'Elapse (v)', '/ɪˈlæps/', '(thời gian) trôi qua', 'if a period of time elapses, it passes SYNONYM : Go by', 'Topic Vocabulary', 1, 10),
    (v_topic_id, 'Era (n)', '/ˈɪərə/', 'Kỷ nguyên, thời đại', 'a period of time, usually in history, that is different from other periods because of particular characteristics or events', 'Topic Vocabulary', 1, 11),
    (v_topic_id, 'Eternal (adj)', '/ɪˈtɜːnl/', 'Vĩnh viễn, không ngừng', 'without an end; existing or continuing forever', 'Topic Vocabulary', 1, 12),
    (v_topic_id, 'Expire (v)', '/ɪkˈspaɪə(r)/', 'Hết hạn, hết hiệu lực', 'to be no longer legally acceptable because the period of time for which it could be used has ended SYNONYM : Run out', 'Topic Vocabulary', 1, 13),
    (v_topic_id, 'Frequency (n)', '/ˈfriːkwənsi/', 'Tính thường xuyên/ thường hay xảy ra', 'the rate at which something happens or is repeated', 'Topic Vocabulary', 1, 14),
    (v_topic_id, 'Instantaneous (adj)', '/ˌɪnstənˈteɪniəs/', 'Tức thời (xảy ra ngay lập tức)', 'happening immediately or very quickly', 'Topic Vocabulary', 1, 15),
    (v_topic_id, 'Interim (n, adj)', '/ˈɪntərɪm/', 'Sự dàn xếp tạm thời - Tạm thời, tạm quyền', 'during the period of time between two events; until a particular event happens - intended to last for only a short time until somebody/something more permanent is found. E.g. An interim account', 'Topic Vocabulary', 1, 16),
    (v_topic_id, 'Interval (n)', '/ˈɪntəvl/', 'Thời gian giải lao, khoảng nghỉ (giữa hai sự kiện)', 'a period of time between two events', 'Topic Vocabulary', 1, 17),
    (v_topic_id, 'Lapse (v,n)', '/læps/', 'Mất hiệu lực - Sự nhầm lẫn', 'to no longer be legally recognized because the period of time that it lasts has come to an end - a small mistake, especially one that is caused by forgetting something or by being careless', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'Lifetime (n)', '/ˈlaɪftaɪm/', 'suốt đời', 'the length of time that somebody lives or that something lasts', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'Long-standing (adj)', '/ˌlɒŋ ˈstændɪŋ/', 'Lâu đời', 'that has existed or lasted for a long time', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'Millennium (n)', '/mɪˈleniəm/', 'Thiên niên kỷ (một nghìn năm), thời đại hoàng kim', 'a period of 1 000 years, especially as calculated before or after the birth of Christ', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'Obsolete (adj)', '/ˈɒbsəliːt/', 'Cổ xưa, quá hạn, đã lỗi thời', 'no longer used because something new has been invented SYNONYM : out of date', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'Overdue (adj)', '/ˌəʊvəˈdjuː/', 'Quá hạn, quá chậm', 'not paid, done, returned, etc. by the required or expected time', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'Period (n)', '/ˈpɪəriəd/', 'Giai đoạn', 'an amount of time during which something happens', 'Topic Vocabulary', 1, 24),
    (v_topic_id, 'Permanent (adj)', '/ˈpɜːmənənt/', 'Lâu dài, vĩnh cửu, cố định', 'lasting for a long time or for all time in the future; existing all the time', 'Topic Vocabulary', 1, 25),
    (v_topic_id, 'Phase (n)', '/feɪz/', 'Thời kỳ, giai đoạn', 'a stage in a process of change or development', 'Topic Vocabulary', 1, 26),
    (v_topic_id, 'Postpone (v)', '/pəˈspəʊn/', 'Hoãn lại', 'to arrange for an event, etc. to take place at a later time or date than originally planned SYNONYM : put off', 'Topic Vocabulary', 1, 27),
    (v_topic_id, 'Prior (adj)', '/ˈpraɪə(r)/', 'Trước, ưu tiên', 'happening or existing before something else or before a particular time', 'Topic Vocabulary', 1, 28),
    (v_topic_id, 'Prompt (adj)', '/prɒmpt/', 'Nhanh chóng, ngay lập tức', 'done without delay SYNONYM : immediate', 'Topic Vocabulary', 1, 29),
    (v_topic_id, 'Provisional (adj)', '/prəˈvɪʒənl/', 'Tạm thời, lâm thời', 'arranged for the present time only and likely to be changed in the future', 'Topic Vocabulary', 1, 30),
    (v_topic_id, 'Punctual (adj)', '/ˈpʌŋktʃuəl/', 'Đúng giờ', 'happening or doing something at the arranged or correct time; not late', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'Seasonal (adj)', '/ˈsiːzənl/', 'Từng thời vụ, thay đổi theo mùa', 'happening or needed during a particular season; varying with the seasons', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'Simultaneous (adj)', '/ˌsɪmlˈteɪniəs/', 'Đồng thời, cùng lúc', 'happening or done at the same time as something else', 'Topic Vocabulary', 1, 33),
    (v_topic_id, 'Span (v, n)', '/spæn/', 'Kéo dài qua (thời gian) - Khoảng thời gian', 'to last all through a period of time or to cover the whole of it - the length of time that something lasts or is able to continue', 'Topic Vocabulary', 1, 34),
    (v_topic_id, 'Spell (n)', '/spel/', 'Thời gian ngắn', 'a short period of time during which something lasts', 'Topic Vocabulary', 1, 35),
    (v_topic_id, 'Stint (n)', '/stɪnt/', 'Khoảng thời gian làm việc gì đó', 'a period of time that you spend working somewhere or doing a particular activity', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'Subsequent (adj)', '/ˈsʌbsɪkwənt/', 'Sau đó, tiếp theo', 'happening or coming after something else', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'Temporary (adj)', '/ˈtemprəri/', 'Tạm thời, nhất thời', 'lasting or intended to last or be used only for a short time; not permanent', 'Topic Vocabulary', 1, 38),
    (v_topic_id, 'Timely (adj)', '/ˈtaɪmli/', 'Kịp lúc, hợp thời', 'happening at exactly the right time SYNONYM: opportune', 'Topic Vocabulary', 1, 39),
    (v_topic_id, 'Vintage (n, adj)', '/ˈvɪntɪdʒ/', 'Rượu vang chính vụ - Cổ điển', 'the wine that was produced in a particular year or place; the year in which it was produced - produced in the past, and typical of the period in which it was made', 'Topic Vocabulary', 1, 40),
    (v_topic_id, 'Civil service (n phr)', '/ˌsɪvl ˈsɜːvɪs/', 'dân chính, công vụ', 'the government departments in a country and the people who work for them, except the armed forces, judges and elected politicians', 'Topic Vocabulary', 1, 41),
    (v_topic_id, 'Client (n)', '/ˈklaɪənt/', 'Khách hàng', 'a person who uses the services or advice of a professional person or organization', 'Topic Vocabulary', 1, 42),
    (v_topic_id, 'Colleague (n)', '/ˈkɒliːɡ/', 'Đồng nghiệp', 'a person that you work with, especially in a profession or a business', 'Topic Vocabulary', 1, 43),
    (v_topic_id, 'Consultant (n)', '/kənˈsʌltənt/', 'Cố vấn, người tư vấn', 'a person who knows a lot about a particular subject and is employed to give advice about it to other people', 'Topic Vocabulary', 1, 44),
    (v_topic_id, 'Effective (adj)', '/ɪˈfektɪv/', 'Có hiệu quả, có hiệu lực', 'producing the result that is wanted or intended; producing a successful result', 'Topic Vocabulary', 1, 45),
    (v_topic_id, 'Efficient (adj)', '/ɪˈfɪʃnt/', 'Có năng lực, có năng suất cao, có hiệu quả', 'doing something in a good, careful and complete way with no waste of time, money or energy', 'Topic Vocabulary', 1, 46),
    (v_topic_id, 'Executive (n)', '/ɪɡˈzekjətɪv/', 'Người điều hành', 'a person who has an important job as a manager of a company or an organization', 'Topic Vocabulary', 1, 47),
    (v_topic_id, 'Fire (v)', '/ˈfaɪə(r)/', 'Sa thải, đuổi việc', 'to shoot bullets, etc. from a gun or other weapon', 'Topic Vocabulary', 1, 48),
    (v_topic_id, 'Headhunt (v)', '/ˈhedhʌnt/', 'Tìm kiếm và tuyển chuyên viên giỏi', 'to find somebody who is suitable for a senior job and persuade them to leave their present job', 'Topic Vocabulary', 1, 49),
    (v_topic_id, 'Leave (n)', '/liːv/', 'Kỳ nghỉ phép, sự được phép nghỉ', 'period of time when you are allowed to be away from work for a holiday or for a special reason', 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'Recruit (v, n)', '/rɪˈkruːt/', 'Tuyển dụng - Thành viên mới, lính mới', 'to find new people to join a company, an organization, the armed forces, etc. -a person who has recently joined the armed forces or the police', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'Redundant (adj)', '/rɪˈdʌndənt/', 'Thất nghiệp, sa thải (do công ty thu nhỏ qui mô, phá sản)', '(of a person) without a job because there is no more work available for you in a company', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'Sack (v)', '/sæk/', 'sa thải', 'to remove someone from a job, usually because they have done something wrong or badly, or sometimes as a way of saving the cost of employing them', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'Strike (v, n)', '/straɪk/', 'Tấn công, đánh đập - Cuộc đình công, cuộc bãi công', 'to hit somebody/something hard or with force - a period of time when an organized group of employees of a company stops working because of an argument over pay or conditions', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'Union (n)', '/ˈjuːniən/', 'liên đoàn lao động', 'an organization that represents the workers in a particular industry and tries to improve pay, conditions.', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'crop up', NULL, 'bất ngờ xảy ra', 'to appear or happen, especially when it is not expected SYNONYM: come up', 'Phrasal Verbs', 2, 56),
    (v_topic_id, 'dive in', NULL, 'bắt đầu làm việc gì một cách say mê.', 'to start doing something in a very enthusiastic way', 'Phrasal Verbs', 2, 57),
    (v_topic_id, 'end up', NULL, 'kết cục, kết thúc', 'to find yourself in a place or situation at the end of a process or period of time', 'Phrasal Verbs', 2, 58),
    (v_topic_id, 'kick off (with)', NULL, 'bắt đầu với cái gì đó', 'to start (with something)', 'Phrasal Verbs', 2, 59),
    (v_topic_id, 'knock off', NULL, 'ngừng làm gì đó, đặc biệt là công việc', 'to stop doing something, especially work', 'Phrasal Verbs', 2, 60),
    (v_topic_id, 'knuckle down', NULL, 'bắt đầu làm việc chăm chỉ ( đặc biệt khi đáng lẽ bạn nên làm trước kia)', 'to start working hard, especially when you should have done this earlier', 'Phrasal Verbs', 2, 61),
    (v_topic_id, 'lay off', NULL, 'đuổi việc, cắt giảm nhân sự', 'to stop employing somebody, especially temporarily, because there is not enough work for them to do SYNONYM: make somebody redundant', 'Phrasal Verbs', 2, 62),
    (v_topic_id, 'lie ahead', NULL, 'hoạch định, chờ đợi trong tương lai', 'to be going to happen to somebody in the future', 'Phrasal Verbs', 2, 63),
    (v_topic_id, 'make up', NULL, 'bồi thường, đền bù - làm hòa - dựng chuyện, bịa đặt', 'work at different times from usual because you have not worked enough at the normal times', 'Phrasal Verbs', 2, 64),
    (v_topic_id, 'press ahead/ on (with)', NULL, 'tiếp tục làm gì đó một cách kiên trì, quyết tâm', 'to continue doing something in a determined way; to hurry forward', 'Phrasal Verbs', 2, 65),
    (v_topic_id, 'set out', NULL, 'bắt tay vào làm gì đó', 'to begin a job, task, etc. with a particular aim or goal', 'Phrasal Verbs', 2, 66),
    (v_topic_id, 'snow under', NULL, 'ngập đầu trong công việc', 'to have more things, especially work, than you feel able to deal with', 'Phrasal Verbs', 2, 67),
    (v_topic_id, 'take on', NULL, 'gánh vác, đảm nhận, thuê ( nhân viên)', 'to employ somebody, accept some work or responsibility', 'Phrasal Verbs', 2, 68),
    (v_topic_id, 'tide over', NULL, 'hỗ trợ, giúp đỡ ( thời kì khó khăn)', 'to help somebody during a difficult period by providing what they need', 'Phrasal Verbs', 2, 69),
    (v_topic_id, 'while away', NULL, 'giết thời gian (dành thời gian để thư giãn)', 'to spend time in a relaxed way when you have nothing else to do', 'Phrasal Verbs', 2, 70),
    (v_topic_id, 'wind down', NULL, 'nghỉ ngơi (sau khi làm việc căng thẳng)', 'to rest or relax after a period of activity or excitement SYNONYM: unwind', 'Phrasal Verbs', 2, 71),
    (v_topic_id, 'a stitch in time (saves nine)', NULL, 'giải quyết ngay lập tức (tránh trường hợp mọi việc tồi tệ hơn)', 'it''s better to solve a problem right away, to stop it becoming a much bigger one.', 'Phrasal Verbs', 2, 72),
    (v_topic_id, 'all in good time', NULL, 'đâu sẽ có đó; cứ bình tĩnh, không phải vội', 'used to tell someone to be patient because something they are waiting for will certainly happen after a period of time, and probably quite soon', 'Phrasal Verbs', 2, 73),
    (v_topic_id, 'at the drop of a hat', NULL, 'ngay lập tức, không chần chừ', 'if you do something at the drop of a hat, you do it immediately without stopping to think about it', 'Phrasal Verbs', 2, 74),
    (v_topic_id, 'before your time', NULL, 'diễn ra trước thời của ai; trước khi ai sinh ra đời', 'something happened or existed before you were born or before you lived or worked somewhere', 'Phrasal Verbs', 2, 75),
    (v_topic_id, 'for good', NULL, 'vĩnh cửu, vĩnh viễn', 'permanently, without the possibility of change in the future', 'Phrasal Verbs', 2, 76),
    (v_topic_id, 'for the time being', NULL, 'hiện tại, lúc này', 'at this time or now', 'Phrasal Verbs', 2, 77),
    (v_topic_id, 'from time to time', NULL, 'thỉnh thoảng', 'sometimes, but not regularly', 'Phrasal Verbs', 2, 78),
    (v_topic_id, 'in/for donkey’s years', NULL, 'trong thời gian rất dài', 'an extremely long time', 'Phrasal Verbs', 2, 79),
    (v_topic_id, 'in the nick of time', NULL, 'vừa kịp lúc, vào phút chót (trước khi quá muộn)', 'just in time to prevent something bad happening', 'Phrasal Verbs', 2, 80),
    (v_topic_id, 'once in a blue moon', NULL, 'hiếm khi', 'very rarely', 'Phrasal Verbs', 2, 81),
    (v_topic_id, 'on the spur of the moment', NULL, 'quyết định tức thời, bất ngờ, bốc đồng', 'suddenly without any planning', 'Phrasal Verbs', 2, 82),
    (v_topic_id, 'the other day', NULL, 'mới đây, hôm nọ, gần đây', 'the recent past or a day that occurred close to the present day', 'Phrasal Verbs', 2, 83),
    (v_topic_id, 'partly/mainly/all about', NULL, 'phần nào/chủ yếu/tất cả về…', NULL, 'Phrases & Collocations', 3, 84),
    (v_topic_id, 'do sth about', NULL, 'thực hiện một điều gì đó để sửa chữa', 'to take some sort of action to correct (a situation) E.g: We need to do something about this problem.', 'Phrases & Collocations', 3, 85),
    (v_topic_id, 'about time', NULL, 'đã đến lúc', 'used to convey that something now happening or about to happen should have happened earlier.', 'Phrases & Collocations', 3, 86),
    (v_topic_id, 'about to do', NULL, 'dự định/sắp làm gì', 'to be going to happen or do something very soon', 'Phrases & Collocations', 3, 87),
    (v_topic_id, 'act your age', NULL, 'cư xử đúng tuổi', 'behave in a manner appropriate to someone of one''s age and not to someone much younger.', 'Phrases & Collocations', 3, 88),
    (v_topic_id, '(at/by/from) the age of', NULL, 'ở/đến/từ độ tuổi…', 'about the age when something needs to be done', 'Phrases & Collocations', 3, 89),
    (v_topic_id, 'under age', NULL, 'dưới tuổi, chưa đủ tuổi', '(of a person) too young to engage legally in a particular activity.', 'Phrases & Collocations', 3, 90),
    (v_topic_id, 'school/working/etc age', NULL, 'tuổi đi học / độ tuổi lao động', 'the age range of children normally attending school / the age at which you are neither too young nor too old to work', 'Phrases & Collocations', 3, 91),
    (v_topic_id, 'with age', NULL, 'theo năm tháng, theo thời gian', 'the length of time', 'Phrases & Collocations', 3, 92),
    (v_topic_id, 'age limit', NULL, 'giới hạn tuổi', 'the age at which a person is allowed or not allowed to do something', 'Phrases & Collocations', 3, 93),
    (v_topic_id, 'age bracket/group', NULL, 'khung tuổi / nhóm tuổi', 'people of a similar age, considered as a group', 'Phrases & Collocations', 3, 94),
    (v_topic_id, '(in the) Stone/Bronze/Iron Age', NULL, 'thời kì đồ đá/ đồng/ sắt', 'the early period in human history when people made tools and weapons only out of stone/ bronze / iron', 'Phrases & Collocations', 3, 95),
    (v_topic_id, 'take/spend ages (doing)', NULL, 'mất/ dành nhiều thời gian để làm việc gì', 'to take a long time', 'Phrases & Collocations', 3, 96),
    (v_topic_id, 'ages ago', NULL, 'cách đây rất lâu.', 'a long time in the past', 'Phrases & Collocations', 3, 97),
    (v_topic_id, 'seems/feels like ages (since)', NULL, 'một thời gian dài trôi qua', 'the person has not been to the place in a long time', 'Phrases & Collocations', 3, 98),
    (v_topic_id, 'run its course', NULL, 'diễn ra tự nhiên', 'to develop or happen in the usual way', 'Phrases & Collocations', 3, 99),
    (v_topic_id, 'in during the course of', NULL, 'trong lúc chuyện gì đang diễn ra', 'while something is happening or continuing', 'Phrases & Collocations', 3, 100);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'in due course', NULL, 'đúng lúc', 'at the appropriate or normal time', 'Phrases & Collocations', 3, 101),
    (v_topic_id, 'on a course', NULL, 'có khả năng xảy ra/ có khả năng thành công như dự kiến', 'likely to happen, or likely to succeed as planned', 'Phrases & Collocations', 3, 102),
    (v_topic_id, 'course of action/events', NULL, 'đường lối/phương hướng hành động', 'Any sequence of activities that an individual or unit may follow', 'Phrases & Collocations', 3, 103),
