  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, '(un)workable', '/ˈwɜːkəbl/', '(adj) (không)có thể làm được, thiết thực, khả thi', NULL, 'Topic Vocabulary', 1, 1),
    (v_topic_id, '1. accelerate (v) /əkˈseləreɪt/', NULL, 'Tăng tốc, thúc đẩy', 'to happen faster or earlier; to make', 'Topic Vocabulary', 1, 2),
    (v_topic_id, '- to come near to somebody/something in distance or time', NULL, 'Đến gần, tiếp cận - Sự tiếp cận', NULL, 'Topic Vocabulary', 1, 3),
    (v_topic_id, '- to rise; to go up; to climb up', NULL, 'Đi lên', NULL, 'Topic Vocabulary', 1, 4),
    (v_topic_id, '4. bounce (v,n) /baʊns/', NULL, 'Nảy lên, tâng lên - Sự nảy lên', 'if something bounces or', 'Topic Vocabulary', 1, 5),
    (v_topic_id, '5. clamber (v) /ˈklæmbə(r)/', NULL, 'Leo lên', 'to climb or move with difficulty or a', 'Topic Vocabulary', 1, 6),
    (v_topic_id, '- to close tightly together', NULL, 'Siết chặt', NULL, 'Topic Vocabulary', 1, 7),
    (v_topic_id, '- to hold somebody/something tightly SYNONYM: grip', NULL, 'Giữ chặt', NULL, 'Topic Vocabulary', 1, 8),
    (v_topic_id, '- to move forward on your hands and knees or with your body close to the ground', NULL, 'Trườn, bò', NULL, 'Topic Vocabulary', 1, 9),
    (v_topic_id, '- to move slowly, quietly and carefully, because you do not want to be seen or heard', NULL, 'Rón rén', NULL, 'Topic Vocabulary', 1, 10),
    (v_topic_id, '- an act of going somewhere suddenly and/or quickly', NULL, 'Xông tới, lao tới', NULL, 'Topic Vocabulary', 1, 11),
    (v_topic_id, '- to come or go down from a higher to a lower level', NULL, 'Đi xuống', NULL, 'Topic Vocabulary', 1, 12),
    (v_topic_id, '- to move along smoothly and slowly in water or air - a large pile of something, especially snow, made by the wind', NULL, 'Trôi dạt - Đống (tuyết)', NULL, 'Topic Vocabulary', 1, 13),
    (v_topic_id, '- to leave your own country to go and live permanently in another country', NULL, 'Di cư', NULL, 'Topic Vocabulary', 1, 14),
    (v_topic_id, '- to move slowly on water or in the air SYNONYM: drift', NULL, 'Trôi nổi', NULL, 'Topic Vocabulary', 1, 15),
    (v_topic_id, '- the steady and continuous movement of something/somebody in one direction', NULL, 'Chảy - dòng chảy', NULL, 'Topic Vocabulary', 1, 16),
    (v_topic_id, 'fumble (v)', '/ˈfʌmbl/', 'Dò dẫm', 'to use your hands in a way that is not smooth or steady or careful when you are doing something or looking for something', 'Topic Vocabulary', 1, 17),
    (v_topic_id, 'gesture (v, n)', '/ˈdʒestʃə(r)/', 'Cử chỉ', 'a movement that you make with your hands, your head or your face to show a particular meaning', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'glide (v)', '/ɡlaɪd/', 'Lướt, trượt', 'to move smoothly and quietly, especially as though it takes no effort', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'grab (v)', '/ɡræb/', 'Chộp lấy, vồ lấy', 'to take or hold somebody/something with your hand suddenly or roughly SYNONYM: seize', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'grasp (v)', '/ɡrɑːsp/', 'Túm, bám', 'to take a strong hold of somebody/something SYNONYM: grip', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'hop (v, n)', '/hɒp/', 'Nhảy lò cò', 'to move by jumping on one foot', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'immigrant (n)', '/ˈɪmɪɡrənt/', 'Người nhập cư', 'a person who has come to live permanently in a different country from the one they were born in', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'jog (v, n)', '/dʒɒɡ/', 'Chạy bộ ( chậm và đều đặn)', 'to run slowly and steadily for a long time, especially for exercise', 'Topic Vocabulary', 1, 24),
    (v_topic_id, 'leap (v, n)', '/liːp/', 'Nhảy ( cao, xa)', 'to jump high or a long way', 'Topic Vocabulary', 1, 25),
    (v_topic_id, 'march (v, n)', '/mɑːtʃ/', 'Hành quân - Cuộc diễu hành', 'to walk with stiff regular steps like a soldier - an act of marching; a journey made by marching', 'Topic Vocabulary', 1, 26),
    (v_topic_id, 'migrate (v)', '/maɪˈɡreɪt/', 'Di trú, di cư', 'to move from one part of the world to another according to the season', 'Topic Vocabulary', 1, 27),
    (v_topic_id, 'point (v)', '/pɔɪnt/', 'Chỉ trỏ', 'to stretch out your finger or something held in your hand towards somebody/something in order to show somebody where a person or thing is', 'Topic Vocabulary', 1, 28),
    (v_topic_id, 'punch (v)', '/pʌntʃ/', 'Đấm', 'to hit somebody/something hard with your fist (= closed hand)', 'Topic Vocabulary', 1, 29),
    (v_topic_id, 'refugee (n)', '/ˌrefjuˈdʒiː/', 'Người tị nạn', 'a person who has been forced to leave their country or home, because there is a war or for political, religious or social reasons', 'Topic Vocabulary', 1, 30),
    (v_topic_id, 'roam (v)', '/rəʊm/', 'Đi lang thang', 'to walk or travel around an area without any definite aim or direction', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'roll (v)', '/rəʊl/', 'Cuộn', 'to turn over and over and move in a particular direction; to make a round object do this', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'rotate (v)', '/rəʊˈteɪt/', NULL, 'to move or turn around a central fixed point; to make something do this', 'Topic Vocabulary', 1, 33),
    (v_topic_id, 'route (n)', '/ruːt/', 'Lộ trình, đường đi', 'a way that you follow to get from one place to another', 'Topic Vocabulary', 1, 34),
    (v_topic_id, 'sink (v)', '/sɪŋk/', 'Chìm', 'to go down below the surface or towards the bottom of a liquid or soft substance', 'Topic Vocabulary', 1, 35),
    (v_topic_id, 'skid (v, n)', '/skɪd/', 'Trượt - Sự trượt', 'to slide forward or to one side in a way that shows a loss of control', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'skip (v)', '/skɪp/', 'Nhảy chân sáo, nhảy dây', 'to move forwards lightly and quickly making a little jump with each step', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'slide (v, n)', '/slaɪd/', 'Lướt, trượt (cố tình, có chủ đích) - Sự trượt', 'to move easily over a smooth or wet surface; to make something move in this way', 'Topic Vocabulary', 1, 38),
    (v_topic_id, 'slip (v)', '/slɪp/', 'Trượt, tuột (do tai nạn)', 'to slide a short distance by accident so that you fall or nearly fall', 'Topic Vocabulary', 1, 39),
    (v_topic_id, 'step (v, n)', '/step/', 'Bước, bước đi - Bước, bước chân', 'to lift your foot and move it in a particular direction or put it on or in something; to move a short distance', 'Topic Vocabulary', 1, 40),
    (v_topic_id, 'stride (v, n)', '/straɪd/', 'Sải bước - Sải chân', 'to walk with long steps in a particular direction', 'Topic Vocabulary', 1, 41),
    (v_topic_id, 'trip (v)', '/trɪp/', 'Trượt chân', 'to catch your foot on something and fall or almost fall', 'Topic Vocabulary', 1, 42),
    (v_topic_id, 'velocity (n)', '/vəˈlɒsəti/', 'Vận tốc, tốc độ', 'the speed of something in a particular direction', 'Topic Vocabulary', 1, 43),
    (v_topic_id, 'wander (v)', '/ˈwɒndə(r)/', 'Đi lang thang', 'to walk slowly around or to a place, often without any particular sense of purpose or direction', 'Topic Vocabulary', 1, 44),
    (v_topic_id, 'wave (v, n)', '/weɪv/', 'Vẫy tay - Sự vẫy tay', 'to move your hand or arm from side to side in the air in order to attract attention, say hello, etc', 'Topic Vocabulary', 1, 45),
    (v_topic_id, 'airline (n)', '/ˈeə.laɪn/', 'Hãng hàng không', 'a business that operates regular services for carrying passengers or goods by aircraft', 'Topic Vocabulary', 1, 46),
    (v_topic_id, 'cargo (n)', '/ˈkɑː.ɡəʊ/', 'Hàng hóa chở trên tàu thủy hoặc máy bay', 'the goods carried by a ship, aircraft, or other large vehicle', 'Topic Vocabulary', 1, 47),
    (v_topic_id, 'carriage (n)', '/ˈkær.ɪdʒ/', 'Toa tàu', 'a separate section of a train for carrying passengers', 'Topic Vocabulary', 1, 48),
    (v_topic_id, 'charter (v)', '/ˈtʃɑː.tər/', 'Thuê (phương tiện)', 'the renting of a vehicle', 'Topic Vocabulary', 1, 49),
    (v_topic_id, 'commute (v)', '/kəˈmjuːt/', 'Đi lại giữa nhà và nơi làm việc', 'to make the same journey regularly between work and home', 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'destination (n)', '/ˌdes.tɪˈneɪ.ʃən/', 'Điểm đến', 'the place where someone is going or where something is being sent or taken', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'hiker (n)', '/ˈhaɪ.kər/', 'Người đi bộ việt dã', 'a person who goes for a long walk in the countryside', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'hitchhiker (n)', '/ˈhɪtʃ.haɪ.kər/', 'Người đi nhờ xe', 'someone who travels by getting free rides in someone else''s vehicle', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'jet lag (n)', '/ˈdʒet ˌlæɡ/', 'Say máy bay', 'the feeling of tiredness and confusion that people experience after making a long journey by plane to a place where the time is different from the place they left', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'legroom (n)', '/ˈleɡ.ruːm/', 'Chỗ để chân', 'the amount of space available for your legs when you are sitting behind another seat', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'load (v, n)', '/ləʊd/', 'Chất hàng', 'to put a lot of things into a vehicle or machine', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'passerby (n)', '/ˈpæs·ərˈbɑɪ/', 'Người qua đường', 'someone who is going past a particular place', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'pedestrian (n)', '/pəˈdes.tri.ən/', 'Khách bộ hành', 'a person who is walking, especially in an area where vehicles go', 'Topic Vocabulary', 1, 58),
    (v_topic_id, 'pier (n)', '/pɪər/', 'Bến tàu, cầu tàu', 'a low structure built at the edge of water, used especially for getting into and out of boats', 'Topic Vocabulary', 1, 59),
    (v_topic_id, 'pilot (v, n)', '/ˈpaɪ.lət/', 'Lái máy bay - Phi công', 'to fly an aircraft', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'quay (n)', '/kiː/', 'Bến cảng', 'a long structure, usually built of stone, where boats can be tied up to take on and off their goods', 'Topic Vocabulary', 1, 61),
    (v_topic_id, 'return fare (n phr)', '/rɪˈtɜːn feə/', 'Vé khứ hồi', 'the amount of money it costs to travel by bus, train, plane, etc. to a place and back again', 'Topic Vocabulary', 1, 62),
    (v_topic_id, 'round trip (n phr)', '/ˌraʊnd ˈtrɪp/', 'chuyến đi khứ hồi', 'you go on a journey and return to where you started from', 'Topic Vocabulary', 1, 63),
    (v_topic_id, 'steer (v)', '/stɪər/', 'Lái', 'to control the direction of a vehicle', 'Topic Vocabulary', 1, 64),
    (v_topic_id, 'steward (n)', NULL, 'Người phục vụ ( hành khách)', 'a man whose job is to look after and helps and serves passengers.', 'Topic Vocabulary', 1, 65),
    (v_topic_id, 'Cordon off', NULL, 'Bao vây, cách ly', 'to stop people from getting into an area by surrounding it with police, soldiers, etc.', 'Topic Vocabulary', 1, 66),
    (v_topic_id, 'Creep up on', NULL, 'Tiến lại gần ai đó từ phía sau', 'to move slowly nearer to somebody, usually from behind, without being seen or heard', 'Topic Vocabulary', 1, 67),
    (v_topic_id, 'Fall behind', NULL, 'Bị tụt lại phía sau', 'to fail to keep level with somebody/something', 'Topic Vocabulary', 1, 68),
    (v_topic_id, 'Go astray', NULL, 'Bị lạc, sai hướng', 'to go in the wrong direction or to have the wrong result', 'Topic Vocabulary', 1, 69),
    (v_topic_id, 'Head off', NULL, 'Làm đổi hướng', 'to get in front of somebody in order to make them turn back or change direction', 'Topic Vocabulary', 1, 70),
    (v_topic_id, 'Hold back', NULL, 'Ngăn cản ai/cái gì', 'to prevent somebody/something from moving forward or crossing something', 'Topic Vocabulary', 1, 71),
    (v_topic_id, 'Move in (with)', NULL, 'bắt đầu ở nhà mới', 'to start to live in your new home', 'Topic Vocabulary', 1, 72),
    (v_topic_id, 'Move on', NULL, 'Bắt đầu làm/ thảo luận gì mới', 'to start doing or discussing something new', 'Topic Vocabulary', 1, 73),
