  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'Upright', '/ˈʌpraɪt/', '(adv) thẳng đứng', NULL, 'Topic Vocabulary', 1, 1),
    (v_topic_id, 'Upward(s)', '/ˈʌpwəd/', '( adj) hướng lên, đi lên', NULL, 'Topic Vocabulary', 1, 2),
    (v_topic_id, 'Upwardly', '/ˈʌpwədli/', '( adv) hướng lên, đi lên', NULL, 'Topic Vocabulary', 1, 3),
    (v_topic_id, 'allege (v)', '/əˈledʒ/', 'Viện lẽ, gán tội', 'to state something as a fact but without giving proof', 'Topic Vocabulary', 1, 4),
    (v_topic_id, 'ambiguous (adj)', '/æmˈbɪɡ.ju.əs/', 'Lưỡng nghĩa, nhập nhằng, mơ hồ', 'having or expressing more than one possible meaning, sometimes intentionally', 'Topic Vocabulary', 1, 5),
    (v_topic_id, 'assert (v)', '/əˈsɜːt/', 'Khẳng định', 'to state clearly and definitely that something is true', 'Topic Vocabulary', 1, 6),
    (v_topic_id, 'blunt (adj)', '/blʌnt/', 'Cùn, thẳng thừng, không giữ ý tứ', 'very direct; saying exactly what you think without trying to be polite', 'Topic Vocabulary', 1, 7),
    (v_topic_id, 'boast (v, n)', '/bəʊst/', 'Khoác lác', 'to talk in a way that shows you are too proud of something that you have or can do', 'Topic Vocabulary', 1, 8),
    (v_topic_id, 'clarification (n)', '/klærəfɪˈkeɪʃn/', 'Sự làm sáng tỏ', 'the act or process of making something clearer or easier to understand', 'Topic Vocabulary', 1, 9),
    (v_topic_id, 'colloquial (adj)', '/kəˈləʊ.kwi.əl/', 'Thông tục (từ, cụm từ)', 'informal and more suitable for use in speech than in writing', 'Topic Vocabulary', 1, 10),
    (v_topic_id, 'comprehend (v)', '/kɒm.prɪˈhend/', 'Hiểu', 'to understand something completely', 'Topic Vocabulary', 1, 11),
    (v_topic_id, 'confide (v)', '/kənˈfaɪd/', 'Tâm sự, thổ lộ', 'to tell something secret or personal to someone who you trust not to tell anyone else', 'Topic Vocabulary', 1, 12),
    (v_topic_id, 'confirm (v)', '/kənˈfɜːm/', 'Xác nhận', 'to make an arrangement or meeting certain, often by phone or writing', 'Topic Vocabulary', 1, 13),
    (v_topic_id, 'context (n)', '/ˈkɒntekst/', 'Ngữ cảnh, bối cảnh', 'the situation in which something happens and that helps you to understand it', 'Topic Vocabulary', 1, 14),
    (v_topic_id, 'contradict (v)', '/kɒn.trəˈdɪkt/', 'Nói trái lại, mâu thuẫn với', 'to say that something that somebody else has said is wrong, and that the opposite is true', 'Topic Vocabulary', 1, 15),
    (v_topic_id, 'convey (v)', '/kənˈveɪ/', 'Truyền tải, truyền đạt', 'to express a thought, feeling, or idea so that it is understood by other people', 'Topic Vocabulary', 1, 16),
    (v_topic_id, 'declare (v)', '/dɪˈkleər/', 'Tuyên bố, công bố', 'to announce something clearly, firmly, publicly, or officially', 'Topic Vocabulary', 1, 17),
    (v_topic_id, 'denounce (v)', '/dɪˈnaʊns/', 'Tố cáo, lên án', 'to criticize something or someone strongly and publicly', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'disclose (v)', '/dɪˈskləʊz/', 'Tiết lộ, để lộ ra', 'to make something known publicly, or to show something that was hidden', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'exaggerate (v)', '/ɪɡˈzædʒ.ə.reɪt/', 'Phóng đại, thổi phồng', 'to make something seem larger, more important, better, or worse than it really is', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'flatter (v)', '/ˈflæt.ər/', 'Tâng bốc, nịnh hót', 'to praise someone in order to make them feel attractive or important, sometimes in a way that is not sincere', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'gist (n)', '/dʒɪst/', 'Điểm chính, ý tổng quất', 'the most important pieces of information about something, or general information without details', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'hint (v, n)', '/hɪnt/', 'Dấu hiệu, dấu vết, sự gợi ý', 'something that you say or do that shows what you think or want, usually in a way that is not direct', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'illegible (adj)', '/ɪˈledʒ.ə.bəl/', 'Khó đọc (chữ viết…)', 'impossible or almost impossible to read because of being very untidy or not clear', 'Topic Vocabulary', 1, 24),
    (v_topic_id, 'inkling (n)', '/ˈɪŋ.klɪŋ/', 'có cảm giác chuyện gì đó đúng, có thể xảy ra nhưng không chắc/ dự cảm', 'a feeling that something is true or likely to happen, although you are not certain', 'Topic Vocabulary', 1, 25),
    (v_topic_id, 'insist (v)', '/ɪnˈsɪst/', 'Nài nỉ, khăng khăng (on)', 'to say firmly or demand forcefully, especially when others disagree with or oppose what you say', 'Topic Vocabulary', 1, 26),
    (v_topic_id, 'jargon (n)', '/ˈdʒɑː.ɡən/', 'Biệt ngữ, từ chuyên ngành', 'special words and phrases that are used by particular groups of people, especially in their work', 'Topic Vocabulary', 1, 27),
    (v_topic_id, 'literal (adj)', '/ˈlɪt.ər.əl/', 'Theo đúng nguyên văn, theo nghĩa đen', 'The literal meaning of a word is its original, basic meaning', 'Topic Vocabulary', 1, 28),
    (v_topic_id, 'mumble (v, n)', '/ˈmʌm.bəl/', 'Nói lầm bầm', 'to speak quietly and in a way that is not clear so that the words are difficult to understand', 'Topic Vocabulary', 1, 29),
    (v_topic_id, 'murmur (v, n)', '/ˈmɜː.mər/', 'Rì rầm, rì rào, tiếng rì rào', 'to speak or say something very quietly', 'Topic Vocabulary', 1, 30),
    (v_topic_id, 'petition (n)', '/pəˈtɪʃ.ən/', 'Đơn kiến nghị, đơn thỉnh cầu', 'a document signed by a large number of people demanding or asking for some action from the government or another authority', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'placard (n)', '/ˈplæk.ɑːd/', 'Yết thị, áp phích', 'a large written or printed notice that is put in a public place or carried on a stick in a march', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'quibble (v)', '/ˈkwɪb.əl/', 'Cãi vã về những bất đồng vặt', 'to argue about, or say you disapprove of, something that is not important', 'Topic Vocabulary', 1, 33),
    (v_topic_id, 'rant (v, n)', '/rænt/', 'Nói, viết, la huênh hoang, lời nói rỗng tuếch', 'to speak, write or shout in a loud, uncontrolled, or angry way, often saying confused or silly things', 'Topic Vocabulary', 1, 34),
    (v_topic_id, 'rave (v)', '/reɪv/', 'Nói như điên như dại', 'to speak in an uncontrolled way, usually because you are upset or angry, or because you are ill', 'Topic Vocabulary', 1, 35),
    (v_topic_id, 'relevant (adj)', '/ˈrel.ə.vənt/', 'Có liên quan', 'connected with what is happening or being discussed', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'scribble (v, n)', '/ˈskrɪb.əl/', 'Viết ngoáy, viết cẩu thả', 'to write or draw something quickly or carelessly', 'Topic Vocabulary', 1, 37),
