    (v_topic_id, 'appreciate (v)', '/əˈpriːʃieɪt/', 'đánh giá cao, hiểu rõ giá trị - biết ơn', 'to understand the true nature of situation, and realise why it is important or serious - to be grateful for something', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'catastrophe (n)', '/kəˈtæstrəfi/', 'thảm họa, tai họa lớn', 'an event that cause a lot of damage or makes lot of people suffer - SYNONYM: disaster', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'crop (n)', '/krɒp/', 'cây lương thực - mùa vụ', 'a plant grow for food, usually on a farm - the total amount of a crop that is collected in one season', 'Topic Vocabulary', 1, 38),
