    (v_topic_id, 'famine (n)', '/ˈfæmɪn/', 'nạn đói', 'a serious lack of food that continues for a long time and causes many people in a country to become ill or die', 'Topic Vocabulary', 1, 42),
    (v_topic_id, 'flood (v, n)', '/flʌd/', 'làm ngập lụt, tràn ngập - lũ lụt, nạn lụt', 'if water floods a place, it covers it - a large amount of water that covers an area that was dry before', 'Topic Vocabulary', 1, 43),
    (v_topic_id, 'fossil fuels (n phr)', '/ˈfɒsl fjuːəl/', 'nhiên liệu hóa thạch', 'fuel such as coal or oil, made from decayed material from animals or', 'Topic Vocabulary', 1, 44),
    (v_topic_id, 'global warming (n phr)', '/ˌɡləʊbl ˈwɔːmɪŋ/', 'sự ấm lên toàn cầu', 'an increase in the average temperature of the Earth', 'Topic Vocabulary', 1, 45),
    (v_topic_id, 'greenery (n)', '/ˈɡriːnəri/', 'cây cỏ', 'green plants that are growing somewhere or used as decoration', 'Topic Vocabulary', 1, 46),
    (v_topic_id, 'habitat (n)', '/ˈhæbɪtæt/', 'môi trường sống, nơi sống', 'the type of place that an animal normally lives in or a plant normally grows in', 'Topic Vocabulary', 1, 47),
    (v_topic_id, 'harvest (v, n)', '/ˈhɑːvɪst/', 'thu hoạch, gặt hái - mùa gặt, vụ thu hoạch', 'to collect a crop from the fields - the time when the crop is collected', 'Topic Vocabulary', 1, 48),
