    (v_topic_id, 'instinct (n)', '/ˈɪn.stɪŋkt/', 'bản năng', 'a natural tendency to behave in a particular way that people and animals are born with and that they obey without knowing why', 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'natural disaster (n phr)', '/ˌnætʃrəl dɪˈzɑːstə(r)/', 'thiên tai, thảm họa thiên nhiên', 'something very bad that happens and causes a lot of damage or kills a lot of people', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'resource (n)', '/rɪˈsɔːs/', 'tài nguyên', 'things such as coal, trees and oil that exist in nature and be used by people', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'scarce (adj)', '/skeəs/', 'khan hiếm, ít có', 'if something is scarce, there is not very much of it', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'species (n)', '/ˈspiːʃiːz/', 'giống loài', 'a plant or animal group whose members all have similar general features and are able to produce young plants or animals together', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'chance upon', NULL, 'tình cờ tìm thấy, tình cờ gặp', 'find or see someone or something when you did not expect to', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'come across', NULL, 'tình cờ gặp, nhìn thấy', 'meet someone or find something by chance', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'cool down', NULL, 'làm lạnh xuống, làm nguội đi', 'become cooler, or make something cooler', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'cut back (on)', NULL, 'cắt giảm', 'reduce the amount of something, especially money that you spend', 'Topic Vocabulary', 1, 58),
    (v_topic_id, 'die out', NULL, 'trở nên hiếm, ít dần rồi biến mất hoàn toàn', 'become weaker or less common and then disappear completely', 'Topic Vocabulary', 1, 59),
    (v_topic_id, 'dig up', NULL, 'di chuyển cái gì từ mặt đất - đào, khai quật', 'remove something under the ground by digging; did holes in an area of land; find information by searching carefully', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'dry up', NULL, 'khô cạn, cạn kiệt - không còn tồn tại, khả dụng (ngừng cung cấp)', 'if something dries up or is dried up, all the water comes out of it; stop being available', 'Topic Vocabulary', 1, 61),
    (v_topic_id, 'get through', NULL, 'tiêu thụ hết, sử dụng hết - vượt qua - hoàn thành công việc', 'use or finish something; manage to deal with a difficult situation or stay alive until it is over; finish dealing with some work, a subject, etc', 'Topic Vocabulary', 1, 62),
    (v_topic_id, 'heat up', NULL, 'làm nóng, hâm nóng', 'make something hot, become hot', 'Topic Vocabulary', 1, 63),
    (v_topic_id, 'kill off', NULL, 'tiêu diệt, hủy diệt', 'destroys living things so that most or all of them are dead', 'Topic Vocabulary', 1, 64),
    (v_topic_id, 'put down to', NULL, 'qui cho là', 'if you put something down to a particular reason you, think it has happened for that reason', 'Topic Vocabulary', 1, 65),
    (v_topic_id, 'slip up', NULL, 'mắc lỗi, sai lầm', 'make a careless mistake slip-up(n)', 'Topic Vocabulary', 1, 66),
    (v_topic_id, 'spring up', NULL, 'mọc lên, nổi lên, hiện ra, nảy ra', 'appear or be produced suddenly and quickly', 'Topic Vocabulary', 1, 67),
    (v_topic_id, 'store up', NULL, 'dự trữ, tích trữ, tích lũy', 'keep a lot of something so that you can use it later - do something that will cause problems in the future', 'Topic Vocabulary', 1, 68),
    (v_topic_id, 'throw out', NULL, 'vứt bỏ ( thứ gì đó không cần dùng nữa) - trục xuất - từ chối', 'get rid of something that you no longer want - force someone to leave a place or group - if someone in authority throws out a plan, proposal, etc they refuse to accept it', 'Topic Vocabulary', 1, 69),
    (v_topic_id, 'throw up', NULL, 'đề xuất vấn đề, ý tưởng - tạo ra bụi hoặc nước bay vào không khí', 'produce something new or unexpected - cause something such as dust or water to rise into the air', 'Topic Vocabulary', 1, 70),
    (v_topic_id, 'an act of God', NULL, 'thiên tai bất ngờ (ngoài tầm kiểm soát của con người)', 'an event such as flood lightning or an earthquake that is produced by natural forces, and that people have no control over', 'Topic Vocabulary', 1, 71),
    (v_topic_id, 'come rain or shine', NULL, 'dù thế nào đi chăng nữa', 'use for say that something always happens or someone always does something despite bad weather or difficult conditions - = whatever happens', 'Topic Vocabulary', 1, 72),
    (v_topic_id, 'down on your luck', NULL, 'gặp vận rủi, không may mắn', 'having a long period of difficulty finding work and earning money', 'Topic Vocabulary', 1, 73),
    (v_topic_id, 'draw on the short straw', NULL, 'bị bắt làm việc mình không mong muốn', 'be chosen to do something unpleasant', 'Topic Vocabulary', 1, 74),
    (v_topic_id, 'have green fingers', NULL, 'có tài trồng cây, làm vườn', 'be good at growing plants', 'Topic Vocabulary', 1, 75),
    (v_topic_id, 'let nature take its course', NULL, 'để mọi thứ phát triển tự nhiên mà không cố gắng can thiệp vào nó', 'allow something to develop without trying to influence it', 'Topic Vocabulary', 1, 76),
    (v_topic_id, 'no rhyme or reason', NULL, 'không có lời giải thích rõ ràng, thích hợp', 'use for emphasizing that there is no reason or explanation for something', 'Topic Vocabulary', 1, 77),
    (v_topic_id, 'out of the blue', NULL, 'hoàn toàn bất ngờ, bất thình lình, không báo trước', 'happening in a way that is sudden and unexpected, and does not seem connected with anything that happen before', 'Topic Vocabulary', 1, 78),
    (v_topic_id, 'the luck of the draw', NULL, 'số phận (hên, xui không đoán trước được)', 'used for saying people have limited control over what life brings them', 'Topic Vocabulary', 1, 79),
    (v_topic_id, 'touch wood', NULL, 'phỉ phui, trộm vía (được dùng khi muốn tránh những điều không may mắn xảy ra )', 'used when you have said that you have had good luck in order to prevent bad luck from happening to you', 'Topic Vocabulary', 1, 80),
    (v_topic_id, 'bet (sth) on', NULL, 'đặt cược', 'to risk money on a future event, for example by investing in a company or product or buying stocks or share s', 'Phrases & Collocations', 3, 81),
    (v_topic_id, 'make a bet with (sb)', NULL, 'đánh cược với ai đó', NULL, 'Phrases & Collocations', 3, 82),
    (v_topic_id, 'safe bet', NULL, 'điều có thể/có lẽ thành công', 'action or situation that is likely to be successful or does not involve much risk', 'Phrases & Collocations', 3, 83),
    (v_topic_id, 'know/say for certain', NULL, 'nói hay biết cái gì chắc chắn', 'to know or say something without doubt', 'Phrases & Collocations', 3, 84),
    (v_topic_id, 'certain to do', NULL, 'chắc chắn làm việc gì đó', 'if something is certain, it will definitely happen or is definitely true', 'Phrases & Collocations', 3, 85),
    (v_topic_id, 'make certain', NULL, 'đảm bảo rằng, chắc chắn rằng', 'to check that something is correct or true to do something in order to be sure that something will happen - = make sure', 'Phrases & Collocations', 3, 86),
    (v_topic_id, 'certain of/about', NULL, 'chắc chắn về', 'having no doubts that something is true', 'Phrases & Collocations', 3, 87),
    (v_topic_id, 'a certain (amount of sth)', NULL, 'một số lượng nhất định', 'some, but not very much', 'Phrases & Collocations', 3, 88),
    (v_topic_id, 'take a chance (on)', NULL, 'đánh liều, mạo hiểm', 'to do something that involves risks', 'Phrases & Collocations', 3, 89),
    (v_topic_id, 'leave to chance', NULL, 'để mọi việc được sắp đặt ngẫu nhiên; mặc kệ kết quả/tác động từ bên ngoài ra sao', 'to not try to change the way that something is developing or happening', 'Phrases & Collocations', 3, 90),
    (v_topic_id, 'by chance', NULL, 'tình cờ', 'by luck; without planning', 'Phrases & Collocations', 3, 91),
    (v_topic_id, 'by any chance', NULL, 'có thể', 'used in enquiring about the possibility of something = possibly', 'Phrases & Collocations', 3, 92),
    (v_topic_id, 'the/sb’s chances of (doing)', NULL, 'khả năng để thành công', 'how likely it is that someone will succeed', 'Phrases & Collocations', 3, 93),
    (v_topic_id, 'the chance to do', NULL, 'cơ hội để làm gì đó', 'a time or situation which you can use to do something that you want to do', 'Phrases & Collocations', 3, 94),
    (v_topic_id, 'second chance', NULL, 'cơ hội lần thứ hai', 'help given to someone who has failed, in the hope that they will succeed this time', 'Phrases & Collocations', 3, 95),
    (v_topic_id, 'last chance', NULL, 'cơ hội cuối cùng', 'the last or final opportunity to get, have, do, or achieve something', 'Phrases & Collocations', 3, 96),
    (v_topic_id, 'pure/sheer chance', NULL, 'không lên kế hoạch trước', 'not at all planned', 'Phrases & Collocations', 3, 97),
    (v_topic_id, 'there’s every/no chance that', NULL, 'cơ hội tốt/ không thể nào', 'a good chance/ that is completely impossible or incredibly unlikely', 'Phrases & Collocations', 3, 98),
    (v_topic_id, 'by dint of', NULL, 'bởi vì, do bởi', 'by means of', 'Phrases & Collocations', 3, 99),
    (v_topic_id, 'waste disposal', NULL, 'máy xử lý chất thải; sự xử lý chất thải', 'an electrical machine, connected to a kitchen sink, that cuts up food waste so that it will flow easily through the pipes', 'Phrases & Collocations', 3, 100);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'at sb’s disposal', NULL, 'có sẵn cho ai đó sử dụng', 'available for someone to use', 'Phrases & Collocations', 3, 101),
    (v_topic_id, 'at the disposal of', NULL, 'sẵn lòng giúp đỡ ai đó', 'ready and available to help or serve someone.', 'Phrases & Collocations', 3, 102),
    (v_topic_id, 'find yourself (doing)', NULL, 'thấy chính mình làm điều gì đó', 'discover what you are really like and what you want to do', 'Phrases & Collocations', 3, 103),
    (v_topic_id, 'find sb doing', NULL, 'thấy ai đó làm điều gì đó bất ngờ', 'to discover somebody/something doing something or in a particular situation, especially when this is unexpected', 'Phrases & Collocations', 3, 104),
    (v_topic_id, 'find sth difficult/ interesting/etc', NULL, 'cảm thấy điều gì đó khó khăn/ thú vị', NULL, 'Phrases & Collocations', 3, 105),
    (v_topic_id, 'find your way', NULL, 'tìm ra đúng đường cần đi', 'to reach a place by discovering the right way to get there', 'Phrases & Collocations', 3, 106),
    (v_topic_id, 'green politics', NULL, 'chính trị xanh ( là hệ thống bao gồm các tư tưởng chính trị nhằm tạo ra một xã hội xanh, sạch và thân thiện với môi trường)', 'is a political ideology that aims to create an ecologically sustainable society rooted in environmentalism, nonviolence, social justice, and grassroots democracy', 'Phrases & Collocations', 3, 107),
    (v_topic_id, 'green belt', NULL, 'vành đai xanh', 'a strip of countryside round a city or town where building is not allowed', 'Phrases & Collocations', 3, 108),
    (v_topic_id, '(give sb) the green light', NULL, 'bật đèn xanh (ngụ ý cho phép)', 'to give permission for someone to do something or for something to happen', 'Phrases & Collocations', 3, 109),
    (v_topic_id, 'greenhouse', NULL, 'nhà kính', 'a building with a roof and sides made of glass, used for growing plants that need warmth and protection', 'Phrases & Collocations', 3, 110),
    (v_topic_id, 'struck by lightning', NULL, 'bị sét đánh', 'an occurrence of something being hit by lightning', 'Phrases & Collocations', 3, 111),
    (v_topic_id, 'at lightning speed', NULL, 'cực kì nhanh', 'extremely quickly', 'Phrases & Collocations', 3, 112),
    (v_topic_id, 'push your luck', NULL, 'làm việc gì đó mạo hiểm và có thể mang lại rắc rối', 'to try too hard to get a particular result and risk losing wh at you have achieved', 'Phrases & Collocations', 3, 113),
    (v_topic_id, 'wish sb luck', NULL, 'chúc ai đó may mắn', 'to say that one hopes someone will have success', 'Phrases & Collocations', 3, 114),
    (v_topic_id, 'trust to luck', NULL, 'trông vào sự may mắn', 'to believe that the things that should happen will happen', 'Phrases & Collocations', 3, 115),
    (v_topic_id, 'bring you luck', NULL, 'mang lại may mắn', NULL, 'Phrases & Collocations', 3, 116),
    (v_topic_id, 'the luck of the draw', NULL, 'một sự việc gì đó phụ thuộc vào số phận, hên xui, không đoán trước được', 'used to say that the result of something cannot be controlled and depends on chance', 'Phrases & Collocations', 3, 117),
    (v_topic_id, 'a stroke/piece of luck', NULL, 'may mắn bất ngờ', 'something that happens by chance and that helps you to achieve something', 'Phrases & Collocations', 3, 118),
    (v_topic_id, 'as luck would have it', NULL, 'tình cờ, ngẫu nhiên', 'used to say that something happened by chance', 'Phrases & Collocations', 3, 119),
    (v_topic_id, 'in luck', NULL, 'may mắn, gặp may', 'experiencing a surprisingly good sit uation', 'Phrases & Collocations', 3, 120),
    (v_topic_id, 'with any luck', NULL, 'hy vọng điều gì đó có thể xảy ra', 'used before describing an event or a result that you are hoping for', 'Phrases & Collocations', 3, 121),
    (v_topic_id, 'completely/tot ally natural', NULL, 'hoàn toàn tự nhiên', NULL, 'Phrases & Collocations', 3, 122),
    (v_topic_id, 'natural causes', NULL, 'nguyên nhân tự nhiên', 'Nature regarded as a (manifold) source of causation; the regular and predictable causes of a thing. - Old age or disease as causes of death, as distinguished from accident, murder, etc.', 'Phrases & Collocations', 3, 123),
    (v_topic_id, 'natural ability', NULL, 'khả năng tự nhiên', 'ability that is inherited', 'Phrases & Collocations', 3, 124),
    (v_topic_id, 'natural resources', NULL, 'tài nguyên thiên nhiên', 'things such as minerals, forests, coal, etc. that exist in a place and can be used by people', 'Phrases & Collocations', 3, 125),
    (v_topic_id, 'natural selection', NULL, 'chọn lọc tự nhiên', 'the process that results in the continued existence of only', 'Phrases & Collocations', 3, 126),
    (v_topic_id, 'the nature of', NULL, 'tự nhiên,bản chất', 'the usual and expected characteristi cs of life', 'Phrases & Collocations', 3, 127),
    (v_topic_id, 'by nature', NULL, 'bản chất', 'as a result of inborn or inherent qualities; innately', 'Phrases & Collocations', 3, 128),
    (v_topic_id, 'in nature', NULL, 'về bản chất/ trong tự nhiên', NULL, 'Phrases & Collocations', 3, 129),
    (v_topic_id, 'Mother Nature', NULL, 'Mẹ Thiên nhiên', 'nature, especially when considered as a force that controls the weather and all living things', 'Phrases & Collocations', 3, 130),
    (v_topic_id, 'human nature', NULL, 'bản chất con người, nhân tính', 'the ways of behaving, thinking and feeling that are shared by most people and are considered to be normal', 'Phrases & Collocations', 3, 131),
    (v_topic_id, 'second nature', NULL, '(bản năng thứ hai) chỉ thói quen/hành vi/tính cách thực hiện trong một khoảng thời gian dài hoặc thường xuyên và được coi như là yếu tố bẩm sinh hoặc bản năng.', 'If something is second nature to you, you are so familiar with it that you can do it easily without needing to think ve ry much about it', 'Phrases & Collocations', 3, 132),
    (v_topic_id, 'the odds of doing', NULL, 'tỉ lệ/khả năng của một việc làm nào đó', 'the chances of doing something happening', 'Phrases & Collocations', 3, 133),
