    (v_topic_id, 'against all the odds', NULL, 'bất chấp thất bại, bất chấp hoàn cảnh không thuận lợi', 'despite being very likely to fail', 'Phrases & Collocations', 3, 136),
    (v_topic_id, 'rain hard/heavily', NULL, 'mưa lớn', NULL, 'Phrases & Collocations', 3, 137),
