    (v_topic_id, 'weather', NULL, NULL, NULL, 'Phrases & Collocations', 3, 139),
    (v_topic_id, 'weatherproof', NULL, 'chống chịu thời tiết (mưa, gió)', 'not allowing wind or rain to go through', 'Phrases & Collocations', 3, 140),
    (v_topic_id, 'strong/light wind', NULL, 'gió mạnh/gió nhẹ', NULL, 'Phrases & Collocations', 3, 141),
    (v_topic_id, 'gust of wind', NULL, 'cơn gió mạnh', 'sudden strong wind', 'Phrases & Collocations', 3, 142),
    (v_topic_id, 'in the wind', NULL, 'Sắp xảy ra nhưng chưa biết chính xác là khi nào', 'if something is in the wind, people are talking about it and it may happen, but no one is sure', 'Phrases & Collocations', 3, 143),
