    INSERT INTO public.topics (name, icon, category) VALUES ('Unit 14: Quantity & Money', '🎓', 'Destination C1-C2') RETURNING id INTO v_topic_id;
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'abundant (adj)', '/əˈbʌn.dənt/', 'phong phú, dồi dào', 'existing or available in large quantities', 'Topic Vocabulary', 1, 1),
    (v_topic_id, 'ample (adj)', '/ˈӕmpl/', 'đủ, nhiều hơn cần', 'enough, and often more than you need', 'Topic Vocabulary', 1, 2),
    (v_topic_id, 'area (n)', '/ˈeəriə/', 'diện tích, bề mặt, khu vực - phạm vi', 'a place on the surface of something such as a part of your body - around a usual or ordinary level or standard', 'Topic Vocabulary', 1, 3),
    (v_topic_id, 'average (adj,n)', '/ˈӕvəridʒ/', 'trung bình - lấy số trung bình -mức trung bình', 'not very good - dividing the total by the amount of numbers the amount, level, standard, etc that is typical of a group of people or things - an amount that is caculated by adding several numbers together and dividng the total by the orignal number of things you added together', 'Topic Vocabulary', 1, 4),
    (v_topic_id, '5. batch (n,v) /bӕtʃ/', NULL, 'một loạt ( thứ, người) đến hoặc được giải quyết cùng 1 lúc - gom thành nhóm', 'a number of things or people that arrive or are dealt with at the same time - to group things together', 'Topic Vocabulary', 1, 5),
    (v_topic_id, '6. bulk (n) /balk/', NULL, 'phần lớn - kích thước lớn - số lượng nhiều', 'the majority or largerst part of something - something that is very large, wide and solid - if something is bought or sold in buk, it is bought or sold in large quantities', 'Topic Vocabulary', 1, 6),
    (v_topic_id, '7. considerable', NULL, 'đáng kể, to tát', 'large in size, amount or degree', 'Topic Vocabulary', 1, 7),
    (v_topic_id, '(adj)', NULL, NULL, NULL, 'Topic Vocabulary', 1, 8),
    (v_topic_id, '/kən''sidərəbl/', NULL, NULL, NULL, 'Topic Vocabulary', 1, 9),
    (v_topic_id, '8. countless (adj) /´kauntlis/', NULL, 'vô số, vô kể', 'very many, especially more than you think is reasonable', 'Topic Vocabulary', 1, 10),
    (v_topic_id, '9. dimension (n) /dɪˈmɛnʃən/', NULL, 'kích thước, cỡ - khía cạnh, cách thức nhìn nhận vấn đề', 'length, height or width - an aspect, or way of looking at or thinking about something', 'Topic Vocabulary', 1, 11),
    (v_topic_id, '10. diminish (v) /di´miniʃ/', NULL, 'thu nhỏ - giảm bớt', 'to become less - to make something become less', 'Topic Vocabulary', 1, 12),
    (v_topic_id, '11. equation (n) /i''kweiʃn/', NULL, 'phương trình, sự cân bằng - tất cả các khía cạnh khác nhau bạn phải xem xét trong 1 tình huống', 'a statement in mathematics that two sets of numbers or expressions are equal - all the different aspects that you have to consider in a situation', 'Topic Vocabulary', 1, 13),
    (v_topic_id, '12. equidistant (adj) /¸i:kwi´distənt /', NULL, 'khoảng cách bằng nhau từ hai nơi.', 'at the same distance from two places', 'Topic Vocabulary', 1, 14),
    (v_topic_id, '13. expand (v) /ikˈspand/', NULL, 'mở rộng', 'to become or make larger in size and fill more space', 'Topic Vocabulary', 1, 15),
    (v_topic_id, '14. extent (n) /ɪkˈstɛnt/', NULL, 'mức độ - phạm vi', 'the importance of a problem or situation -the size or area of something', 'Topic Vocabulary', 1, 16),
    (v_topic_id, '15. finite (adj) /ˈfaɪnaɪt/', NULL, 'có hạn', 'existing only in limited numbers or amounts or continuing only for a limited time or distance', 'Topic Vocabulary', 1, 17),
    (v_topic_id, '16. force (n,v) /fɔ:s/', NULL, 'đơn vị đo sức mạnh - sức mạnh - sức lực, lực - vũ lực', 'physical strength or violence - the influence or powerful effect that someone has - a power that makes an object move or changes the way it moves', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'fraction (n)', '/´frækʃən/', 'phần nhỏ - phân số', 'a small part or amount of something - a division or part of a whole number, for example 1/2 or 3/4', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'heap (n,v)', '/hip/', 'chất đống - xếp thành đống', 'a large pile of something, especially an untidy pile - to make a big untidy pile of things', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'imbalance (n)', '/im´bæləns/', 'sự mất cân bằng', 'a situation in which the balance between two things not equal or fair', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'immense (adj)', '/i´mens/', 'mênh mông, bao lao', 'extremely large', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'intensity (n)', '/ɪnˈtɛnsɪti/', 'sức mạnh, độ mạnh', 'strength', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'magnitude (n)', '/''mægnitju:d/', 'độ lớn', 'great size, importance or effect', 'Topic Vocabulary', 1, 24),
