    (v_topic_id, 'proportio n (n)', '/prə''pɔ:ʃn/', 'tỉ lệ, phần', 'a quantity of something that is a part or share a of the whole', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'quantity (v)', '/ˈkwɒntɪti/', 'lượng, số lượng', 'to measure or describe something as a quantity', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'damage (n)', NULL, NULL, NULL, 'Topic Vocabulary', 1, 33),
