  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'giggle (v, n)', '/ˈɡɪɡl/', 'cười bẽn lẽn - tiếng cười bẽn lẽn', '(v) to laugh in a silly way because you are embarrassed or nervous or you think that something is funny - (n) a slight, silly, repeated laugh', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'glance (v, n)', '/ɡlɑːns/', 'liếc nhìn - cái nhìn thoáng qua, cái liếc qua', '(v) to look quickly at something/somebody and then look away - (n) a quick look at someone/something', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'glimse (v, n)', '/ɡlɪmps/', 'nhìn lướt qua - cái nhìn thoáng qua', '(v) to see someone/something for a moment or not completely - (n) an occasion when you see someone or something for a moment only', 'Topic Vocabulary', 1, 53),
