    (v_topic_id, 'grimace (v, n)', '/ˈɡrɪməs/', 'nhăn nhó - sự nhăn mặt, vẻ nhăn nhó', '(v) to make an ugly expression with your face to show pain, dislike, etc. - (n) an ugly expression made by twisting your face, used to show pain, dislike, etc.', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'grin (v, n)', '/ɡrɪn/', 'cười toe toét - điệu cười toe toét', '(v) to smile showing your teeth - (n) a big smile that shows your teeth', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'handle (v)', '/ˈhændl/', 'giải quyết, xử lý', 'to deal with a situation, a person, an area of work or a strong emotion', 'Topic Vocabulary', 1, 58),
