    (v_topic_id, 'inertia (n)', '/ɪˈnɜːʃə/', 'trì trệ, ì ạch', 'lack of energy; lack of desire or ability to move or change', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'manners (n)', '/ˈmænə(r)/', 'tác phong, thái độ, cử chỉ', 'behaviour that is considered to be polite in a particular society or culture', 'Topic Vocabulary', 1, 61),
