    (v_topic_id, 'mock (v)', '/mɒk/', 'chế giễu, nhạo báng', 'to laugh at somebody/something in an unkind way, especially by copying what they say or do SYNONYM: make fun of', 'Topic Vocabulary', 1, 64),
    (v_topic_id, 'neglect (v, n)', '/nɪˈɡlekt/', 'thờ ơ, bỏ bê, sao lãng - sự sao lãng, bỏ bê', '(v) to fail to take care of somebody or do something that you should do - (n) the failure to give someone or something the care or attention they need', 'Topic Vocabulary', 1, 65),
