    (v_topic_id, 'keep your hair on', NULL, 'bình tĩnh nào (nói ai đó không tức giận/ buồn)', 'said to tell someone to stop being so angry or upset', 'Idioms', 4, 118),
    (v_topic_id, 'kick yourself', NULL, 'hối hận (vì điều đã làm/ không làm điều gì mà bạn có cơ hội)', 'to be annoyed because you did something stupid or failed to act when you had an opportunity', 'Idioms', 4, 119),
    (v_topic_id, 'let off steam', NULL, 'làm cho hạ hỏa/ nguôi ngoai cơn giận', 'shout or do something that allows you to get rid of anger', 'Idioms', 4, 120),
    (v_topic_id, 'let sleeping dogs lie', NULL, 'chuyện qua rồi hãy cho qua', 'leave a person or situation alone if they might cause you trouble', 'Idioms', 4, 121),
    (v_topic_id, 'never/don’t look a gift horse in the mouth', NULL, 'đừng chê bai/soi xét , đừng bới lông tìm vết', 'if you are given something good, you shoud not complain about it or try to find things that are wrong with it', 'Idioms', 4, 122),
    (v_topic_id, 'up in arms about', NULL, 'tức giận/ bất mãn về điều gì', 'angry and complaining about something', 'Idioms', 4, 123),
