  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'integrate (v)', '/ˈɪntɪɡreɪt/', 'hòa nhập, hội nhập', 'to make someone become a full member of a group or society and be involved completely in its activities', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'interfere (v)', '/ˌɪntəˈfɪə(r)/', 'can thiệp, xen vào', 'to deliberately become involved in a situation and try to influence the way that it develops, although you have no right to do this', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'intermediate (adj)', '/ˌɪntəˈmiːdiət/', 'trung gian, khoảng giữa - trung cấp', 'in between two stages, places, levels, times, etc - at an academic level below advance', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'internal (adj)', '/ɪnˈtɜːnl/', 'bên trong, nội bộ, nội tâm', 'existing or happening inside an object, a building or your body', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'intervene (v)', '/ˌɪntəˈviːn/', 'xen vào, can thiệp', 'to become involved in a situation in order to try to stop or change it', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'intimate (adj)', '/ˈɪntɪmət/', 'thân mật, mật thiết, thân tình', 'an intimate relationship is a very close personal relationship, especially sexual one', 'Topic Vocabulary', 1, 56),
    (v_topic_id, 'involve (v)', '/ɪnˈvɒlv/', 'gồm, bao gồm, bao hàm', 'to include something as a necessary part of an activity, event or situation', 'Topic Vocabulary', 1, 57),
    (v_topic_id, 'joint (adj)', '/dʒɔɪnt/', 'chung (giữa hai hay nhiều người)', 'involving two or more people or done by them together', 'Topic Vocabulary', 1, 58),
    (v_topic_id, 'liken (v)', '/ˈlaɪkən/', 'so sánh, ví von', 'to say that someone or something is similar to someone or something else', 'Topic Vocabulary', 1, 59),
    (v_topic_id, 'link (v,n)', '/lɪŋk/', 'kết nối - liên kết - mối liên kết, mối quan hệ', 'if people, things or events are linked, they are related to each other in some way - to say or show that two things are related, or that one of the things causes the other - a connection between two or more people, places, facts or events, especially when one is affected or caused by the other', 'Topic Vocabulary', 1, 60),
    (v_topic_id, 'merge (v)', '/mɜːdʒ/', 'hòa vào, kết hợp, hợp nhất, sát nhập', 'if two organization merge, or you merge them, they combine to form one bigger organization', 'Topic Vocabulary', 1, 61),
    (v_topic_id, 'mutual (adj)', '/ˈmjuːtʃuəl/', 'lẫn nhau, qua lại', 'felt or done in the same way by each of two or more people', 'Topic Vocabulary', 1, 62),
    (v_topic_id, 'negotiate (v)', '/nɪˈɡəʊʃieɪt/', 'đàm phán, thương lượng, dàn xếp', 'to try to reach an agreement by discussing something in a formal way, especially in a business or political situation', 'Topic Vocabulary', 1, 63),
    (v_topic_id, 'related (adj)', '/rɪˈleɪtɪd/', 'có liên quan, có mối quan hệ', 'if two or more things are related, there is a connection between them', 'Topic Vocabulary', 1, 64),
    (v_topic_id, 'relative (adj)', '/ˈrelətɪv/', 'tương đối', 'having a particular quality when compared to something else', 'Topic Vocabulary', 1, 65),
    (v_topic_id, 'resemblance (n)', '/rɪˈzembləns/', 'sự giống nhau, sự tương tự, sự tương đồng', 'if there is a resemblance between two people or things, they are similar, especially in their appearance', 'Topic Vocabulary', 1, 66),
    (v_topic_id, 'aquaintance (n)', '/əˈkweɪn.təns/', 'người quen', 'someone you know a little, who is not a close friend', 'Topic Vocabulary', 1, 67),
    (v_topic_id, 'adopt (v)', '/əˈdɒpt/', 'chấp nhận, thông qua, làm theo - nhận làm con nuôi', 'to decide to start using a particular idea, plan or method', 'Topic Vocabulary', 1, 68),
    (v_topic_id, 'ancestor (n)', '/ˈænsestə(r)/', 'ông bà tổ tiên', 'someone who is related to you who lived a long time ago', 'Topic Vocabulary', 1, 69),
    (v_topic_id, 'citizen (n)', '/ˈsɪtɪzn/', 'công dân', 'someone who has the right to live permanently in a particularly country and has the right to the legal and social benefits of that country as well as legal obligations towards it', 'Topic Vocabulary', 1, 70),
    (v_topic_id, 'companion (n)', '/kəmˈpænjən/', 'bạn, bạn đồng hành, bạn đời', 'someone who is with you', 'Topic Vocabulary', 1, 71),
    (v_topic_id, 'dependant (n)', '/dɪˈpendənt/', 'người phụ thuộc vào người khác, người sống dựa vào người khác; người được bảo hộ, che chở', 'a child or other relative to whom you give food, money and a home', 'Topic Vocabulary', 1, 72),
    (v_topic_id, 'descendant (n)', '/dɪˈsendənt/', 'con cháu, hậu duệ, người nối dõi', 'a relative of a person who lived in the past', 'Topic Vocabulary', 1, 73),
    (v_topic_id, 'empathise (v)', NULL, 'thấu cảm, đồng cảm', 'to understand how someone feels because you can imagine what it is like to be them', 'Topic Vocabulary', 1, 74),
    (v_topic_id, 'extrovert (n)', '/ˈekstrəvɜːt/', 'người hướng ngoại', 'someone who is very confident, lively and likes social situations', 'Topic Vocabulary', 1, 75),
    (v_topic_id, 'foster (v)', '/ˈfɒstə(r)/', 'nuôi dưỡng, nuôi nấng', 'to look after a child as part of your family for a period of time because the child’s parents cannot look after them', 'Topic Vocabulary', 1, 76),
    (v_topic_id, 'guardian (n)', '/ˈɡɑː.di.ən/', 'người giám hộ', 'someone who is legally responsible for another person such as a child, whose parents have died', 'Topic Vocabulary', 1, 77),
    (v_topic_id, 'introvert (n)', '/ˈɪn.trə.vɜːt/', 'người hướng nội', 'someone who tends to concentrate on their own thoughts and feelings rather than communicating with other people', 'Topic Vocabulary', 1, 78),
    (v_topic_id, 'partner (n)', '/ˈpɑːt.nər/', 'cộng sự, đối tác, bạn đồng hành - người bạn đời', 'someone that you do a particular activity with - someone that you live with and have a sexual relationship with', 'Topic Vocabulary', 1, 79),
    (v_topic_id, 'peer (n)', '/pɪər/', 'người bằng tuổi; người ngang hàng', 'someone who is of the same age as another person', 'Topic Vocabulary', 1, 80),
    (v_topic_id, 'predecessor (n)', '/ˈpriː.dɪˌses.ər/', 'người tiền nhiệm, người đảm nhiệm trước, bậc tiền bối', 'the person who has a job or official position before someone else', 'Topic Vocabulary', 1, 81),
    (v_topic_id, 'sibling (n)', '/ˈsɪb.lɪŋ/', 'anh chị em ruột', 'your siblings are your brothers and sisters', 'Topic Vocabulary', 1, 82),
    (v_topic_id, 'spouse (n)', '/spaʊs/', 'vợ/chồng', 'a husband or wife', 'Topic Vocabulary', 1, 83),
    (v_topic_id, 'stepmother', '/son/', 'mẹ kế/ con trai riêng…', 'someone’s stepmother/son/etc is their stepmother/son/etc because of a second marriage, not because of a biological connection', 'Topic Vocabulary', 1, 84),
    (v_topic_id, 'successor (n)', '/səkˈses.ər/', 'người thừa kế, người kế nghiệp, người kế nhiệm', 'someone who has a position after someone else', 'Topic Vocabulary', 1, 85),
    (v_topic_id, 'sympathise (v)', '/ˈsɪm.pə.θaɪz/', 'thông cảm, đồng tình', 'to behave in a kind way and show that you understand someone’s problems', 'Topic Vocabulary', 1, 86),
    (v_topic_id, 'answer back', NULL, 'cãi lại', 'reply rudely to someone who has more authority than you', 'Phrasal Verbs', 2, 87),
    (v_topic_id, 'ask out', NULL, 'mời hẹn hò, rủ đi hẹn hò', 'invite someone to go with you to a cinema, restaurant, etc because you want to start a romantic or sexual relationship with them', 'Phrasal Verbs', 2, 88),
    (v_topic_id, 'break up', NULL, 'chia tay - đập vụn. đập nhỏ - sự giải tán (đám đông)', 'if two people break up, they end their relationship; break something to make small pieces; if a meeting or other event breaks up, or if you break it up, it ends and people leave', 'Phrasal Verbs', 2, 89),
    (v_topic_id, 'bring out', NULL, 'làm cho (một phẩm chất) được thấy rõ ở ai đó - phát hành, công bố', 'make someone or something show a quality that they have; produce a new product and start to sell it', 'Phrasal Verbs', 2, 90),
    (v_topic_id, 'bring together', NULL, 'họp lại, nhóm lại, gom lại', 'create a situation in which people meet and do something together, especially when they would not usually do so', 'Phrasal Verbs', 2, 91),
    (v_topic_id, 'bump into', NULL, 'tình cờ gặp ai đó - tình cờ va/đụng vào ai đó', 'meet someone unexpectedly; accidentally hit again something', 'Phrasal Verbs', 2, 92),
    (v_topic_id, 'cancel out', NULL, 'bài trừ; triệt tiêu', 'stop something from having any effect', 'Phrasal Verbs', 2, 93),
    (v_topic_id, 'come between', NULL, 'gây ra bất đồng/ tranh cãi - can thiệp, xen vào', 'cause a disagreement or argument between people', 'Phrasal Verbs', 2, 94),
    (v_topic_id, 'crowd around', NULL, 'đổ xô vào, vây quanh điều gì', 'move to a particular place at the same time as a lot of other people', 'Phrasal Verbs', 2, 95),
    (v_topic_id, 'go together', NULL, 'hài hòa, tương thích', 'if two or more things go together, they frequently exist together; if two things go together, they seem good,', 'Phrasal Verbs', 2, 96),
    (v_topic_id, 'meet up', NULL, 'gặp gỡ ai đó', 'come together with someone, either unexpectedly or as planned', 'Phrasal Verbs', 2, 97),
    (v_topic_id, 'open up', NULL, 'cởi mở - khai thông, mở cửa', 'talk more about your personal feelings and experiences; open a locked door, container or building; make it easier to travel or do business in a country', 'Phrasal Verbs', 2, 98),
    (v_topic_id, 'pick on', NULL, 'đối xử tệ, không công bằng', 'keep treating someone badly or unfairly, especially by criticizing them', 'Phrasal Verbs', 2, 99),
    (v_topic_id, 'sound out', NULL, 'thăm dò, kiểm tra xem người khác nghĩ gì', 'try to find out someone’s opinions, ideas, feelings, etc by talking to them', 'Phrasal Verbs', 2, 100);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'take after', NULL, 'trông giống', 'look or behave like an older relative', 'Phrasal Verbs', 2, 101),
    (v_topic_id, 'take to', NULL, 'bắt đầu thích ai đó hoặc một thứ gì đó - bắt đầu thực hiện một thói quen', 'begin to like someone or something; start doing something as a habit', 'Phrasal Verbs', 2, 102),
    (v_topic_id, 'be born with a silver spoon in your mouth', NULL, 'sinh ra trong gia đình giàu có và thành đạt/ sinh ra đã ngậm thìa vàng', 'to have a high social position and be rich from birth', 'Phrasal Verbs', 2, 103),
    (v_topic_id, 'be on the same wavelength', NULL, 'hiểu nhau; đồng tình vì có chung quan điểm hay sở thích/ cùng tầng số (hàm ý hiểu nhau)', 'to think in a similar way and to understand each other well', 'Phrasal Verbs', 2, 104),
    (v_topic_id, 'get on like a house on fire', NULL, 'có mối quan hệ rất tốt với ai đó; làm thân rất nhanh với ai đó', 'If two people get on like a house on fire, they like each other very much and become friends very quickly', 'Phrasal Verbs', 2, 105),
    (v_topic_id, 'in sb’s bad/good books', NULL, 'mất lòng/hài lòng ai đó', 'If you are in someone''s good/bad books, they are pleased/not pleased with you', 'Phrasal Verbs', 2, 106),
