  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'addiction (n)', '/əˈdɪkʃn/', 'sự nghiện (làm gì hoặc sử dụng cái gì).', 'the condition of being unable to stop using or doing something as a habit, especially something harmful.', 'Topic Vocabulary', 1, 1),
    (v_topic_id, 'adore (v)', '/əˈdɔːr/', 'cực kỳ yêu thích.', 'to like something very much', 'Topic Vocabulary', 1, 2),
    (v_topic_id, 'anticipation (n)', '/ænˌtɪsɪˈpeɪʃn/', 'cảm giác phấn khích về điều gì đó sắp xảy ra (thường là điều tốt).', 'a feeling of excitement about something (usually something good) that is going to happen.', 'Topic Vocabulary', 1, 3),
    (v_topic_id, 'appeal (v, n)', '/əˈpiːl/', 'hấp dẫn, lôi cuốn. - sự hấp dẫn, sự thích thú.', 'to attract or interest somebody.', 'Topic Vocabulary', 1, 4),
    (v_topic_id, 'arbitrary (adj)', '/ˈɑːrbɪtreri/', 'tùy tiện, tùy hứng.', '(of an action, a decision, a rule, etc.) not seeming to be based on a reason, system or plan and sometimes seeming unfair.', 'Topic Vocabulary', 1, 5),
    (v_topic_id, 'aspiration (n)', '/ˌæspəˈreɪʃn/', 'khát vọng, tham vọng mạnh mẽ.', 'a strong desire to have or do something.', 'Topic Vocabulary', 1, 6),
    (v_topic_id, 'bear (v)', '/ber/', 'chịu đựng.', 'to be able to accept and deal with something unpleasant. SYNONYM: stand', 'Topic Vocabulary', 1, 7),
    (v_topic_id, 'compulsory (adj)', '/kəmˈpʌlsəri/', 'bắt buộc.', 'that must be done because of a law or a rule. SYNONYM: mandatory', 'Topic Vocabulary', 1, 8),
    (v_topic_id, 'content (adj)', NULL, 'bằng lòng, toại nguyện.', '(with sth) happy and satisfied with what you have. SYNONYM: happy', 'Topic Vocabulary', 1, 9),
    (v_topic_id, 'craving (n)', '/ˈkreɪvɪŋ/', 'sự khao khát.', 'a strong desire for something.', 'Topic Vocabulary', 1, 10),
    (v_topic_id, 'decline (v)', '/dɪˈklaɪn/', 'từ chối (một cách lịch sự).', 'to refuse politely to accept or to do something. SYNONYM: refuse', 'Topic Vocabulary', 1, 11),
    (v_topic_id, 'dedicated (adj)', '/ˈdedɪkeɪtɪd/', 'tận tụy, tận tâm.', 'spending all your time and effort on something. SYNONYM: committed', 'Topic Vocabulary', 1, 12),
    (v_topic_id, 'delight (v)', '/dɪˈlaɪt/', 'làm vui thích, làm vui sướng.', '(delight somebody) to give somebody a lot of pleasure and joy.', 'Topic Vocabulary', 1, 13),
    (v_topic_id, 'desire (v, n)', '/dɪˈzaɪər/', 'sự mong muốn. - mong muốn, khát khao.', 'to want something. - a strong wish to have or do something.', 'Topic Vocabulary', 1, 14),
    (v_topic_id, 'devote (v)', '/dɪˈvəʊt/', 'dành hết cho (việc gì đó)', 'to spend a lot of time or effort doing something.', 'Topic Vocabulary', 1, 15),
    (v_topic_id, 'differentiate (v)', '/ˌdɪfəˈrenʃieɪt/', 'phân biệt.', 'to see or show a difference between things. SYNONYM: distinguish', 'Topic Vocabulary', 1, 16),
    (v_topic_id, 'envy (v, n)', '/ˈenvi/', 'ghen tị, đố kỵ. - sự ghen tị, sự đố kỵ', 'to have the unhappy feeling of wanting to be like someone else or have what they have. - the unhappy feeling of wanting to be in the same situation as somebody else; the feeling of wanting something that somebody else has. SYNONYM: jealousy', 'Topic Vocabulary', 1, 17),
    (v_topic_id, 'fancy (v)', '/ˈfænsi/', 'mong ước, muốn.', 'to want something or want to do something. SYNONYM: feel like', 'Topic Vocabulary', 1, 18),
    (v_topic_id, 'fascination (n)', '/ˌfæsɪˈneɪʃn/', 'sự say mê.', 'the state of being very attracted to and interested in somebody/something.', 'Topic Vocabulary', 1, 19),
    (v_topic_id, 'favour (v, n)', '/ˈfeɪvər/', 'thiên vị. - ân huệ, đặc ân.', 'to treat one person, group or organization better than you treat others, especially in an unfair way. - a thing that you do to help somebody.', 'Topic Vocabulary', 1, 20),
    (v_topic_id, 'greedy (adj)', '/ˈɡriːdi/', 'tham lam.', 'wanting more money, power, food, etc. than you really need.', 'Topic Vocabulary', 1, 21),
    (v_topic_id, 'impulse (n)', '/ˈɪmpʌls/', 'sự thôi thúc.', 'Impulse (to do sth) a sudden strong wish or need to do something, without stopping to think about the results.', 'Topic Vocabulary', 1, 22),
    (v_topic_id, 'inclined (adj)', '/ɪnˈklaɪnd/', 'có khuynh hướng, có chiều hướng.', 'Inclined (to do sth) wanting to do something.', 'Topic Vocabulary', 1, 23),
    (v_topic_id, 'liking (n)', '/ˈlaɪkɪŋ/', 'sự ưa thích, sự mến.', 'Liking (for sb/sth) the feeling that you like somebody or something; the pleasure in something.', 'Topic Vocabulary', 1, 24),
    (v_topic_id, 'mediocre (adj)', '/ˌmiːdiˈəʊkər/', 'tầm thường.', 'not very good; average or below the average in quality.', 'Topic Vocabulary', 1, 25),
    (v_topic_id, 'motive (n)', '/ˈməʊtɪv/', 'lí do, động cơ.', 'a reason for doing something.', 'Topic Vocabulary', 1, 26),
    (v_topic_id, 'mundane (adj)', '/mʌnˈdeɪn/', 'không thú vị (vì quá bình thường)', 'not interesting or exciting, especially because it happens too regularly.', 'Topic Vocabulary', 1, 27),
    (v_topic_id, 'obsessed (adj)', '/əbˈsest/', 'ám ảnh.', 'considering someone or something as so important that you are always thinking about them, in the way that seems extreme to other people.', 'Topic Vocabulary', 1, 28),
    (v_topic_id, 'optional (adj)', '/ˈɑːpʃənl/', 'không bắt buộc.', 'that you can choose to do or have if you want to.', 'Topic Vocabulary', 1, 29),
    (v_topic_id, 'passion (n)', '/ˈpæʃn/', 'cảm xúc mạnh mẽ, sự say mê.', 'a very strong feeling of love, hate, anger, enthusiasm, etc.', 'Topic Vocabulary', 1, 30),
    (v_topic_id, 'praise (v, n)', '/preɪz/', 'tán dương, ca ngợi. - sự tán dương, sự ca ngợi.', 'to express strong approval or admiration for someone or something, especially in public. - an expression of strong approval or adminration.', 'Topic Vocabulary', 1, 31),
    (v_topic_id, 'resolve (v)', '/rɪˈzɑːlv/', 'quyết định.', 'to make a definite decision to do something.', 'Topic Vocabulary', 1, 32),
    (v_topic_id, 'sacrifice (v, n)', '/ˈsækrɪfaɪs/', 'hy sinh. - sự hy sinh.', 'to give up something that is important or valuable to you in order to get or do something that seems more important for yourself or for another person.', 'Topic Vocabulary', 1, 33),
    (v_topic_id, 'strive (v)', '/straɪv/', 'cố gắng, phấn đấu.', 'to try very hard to achieve something.', 'Topic Vocabulary', 1, 34),
    (v_topic_id, 'taste (n)', '/teɪst/', 'khiếu thẩm mỹ, sự tinh tế ý nhị.', 'the ability to judge if something is good or bad in things like art, fashion and social behavior.', 'Topic Vocabulary', 1, 35),
    (v_topic_id, 'tempting (adj)', '/ˈtemptɪŋ/', 'hấp dẫn, lôi cuốn.', 'something that is attractive, and makes people want to have it, do it, etc', 'Topic Vocabulary', 1, 36),
    (v_topic_id, 'urge (v, n)', '/ɜːrdʒ/', 'cố thuyết phục, nài nỉ. - sự thúc đẩy mạnh mẽ.', 'to advise or try hard to persuade somebody to do something. - a strong desire to do something.', 'Topic Vocabulary', 1, 37),
    (v_topic_id, 'welcome (v, adj)', '/ˈwelkəm/', 'vui mừng về cái gì. - được đón tiếp với niềm vui thích.', 'to be pleased to receive or accept something. - if you are welcome or a welcome visitor at a place, people are pleased that you are there.', 'Topic Vocabulary', 1, 38),
    (v_topic_id, 'worthwhile (adj)', '/ˌwɜːrθˈwaɪl/', 'đáng giá, quan trọng.', 'important, pleasant, interesting, etc.; worth spending time, money or effort on.', 'Topic Vocabulary', 1, 39),
    (v_topic_id, 'yearn (v)', '/jɜːrn/', 'ao ước, mong mỏi.', 'to want something very much, especially when it is very difficult to get.', 'Topic Vocabulary', 1, 40),
    (v_topic_id, 'absorbing (adj)', '/əbˈzɔːrbɪŋ/', 'làm say sưa, hấp dẫn.', 'interesting and fun and holding your attention completely.', 'Topic Vocabulary', 1, 41),
    (v_topic_id, 'casual (adj)', '/ˈkæʒuəl/', 'bình thường, tự nhiên.', 'relaxed and informal.', 'Topic Vocabulary', 1, 42),
    (v_topic_id, 'exhilarating (adj)', '/ɪɡˈzɪləreɪtɪŋ/', 'làm vui vẻ, làm hồ hởi.', 'very exciting and great fun', 'Topic Vocabulary', 1, 43),
    (v_topic_id, 'fatigue (n)', '/fəˈtiːɡ/', 'sự mệt mỏi, sự mệt nhọc.', 'a feeling of being extremely tired, usually because of hard work or exercise.', 'Topic Vocabulary', 1, 44),
    (v_topic_id, 'idle (adj)', '/ˈaɪdl/', 'ăn không ngồi rồi, lười nhác. - không có việc gì làm, thất nghiệp.', '(of people) not working hard. SYNONYM: lazy - (of people) without work. SYNONYM: unemployed', 'Topic Vocabulary', 1, 45),
    (v_topic_id, 'indulge (v)', '/ɪnˈdʌldʒ/', 'thỏa mãn.', 'to allow yourself to have or do something that you like, especially something that is considered bad for you.', 'Topic Vocabulary', 1, 46),
    (v_topic_id, 'lifestyle (n)', '/ˈlaɪfstaɪl/', 'lối sống, cách sống.', 'the way in which a person or a group of people lives and works.', 'Topic Vocabulary', 1, 47),
    (v_topic_id, 'leave (n)', '/liːv/', 'sự được phép nghỉ.', 'a period of time when you are allowed to be away from work for a holiday or for a special reason.', 'Topic Vocabulary', 1, 48),
    (v_topic_id, 'outing (n)', '/ˈaʊtɪŋ/', 'cuộc đi chơi.', 'a short journey that you take for enjoyment.', 'Topic Vocabulary', 1, 49),
    (v_topic_id, 'pastime (n)', '/ˈpæstaɪm/', 'trò tiêu khiển, trò giải trí.', 'something that you enjoy doing in your free time. SYNONYM: hobby', 'Topic Vocabulary', 1, 50);
  INSERT INTO public.words (topic_id, word, phonetic, meaning, example_sentence, lesson_name, lesson_order, word_order) VALUES
    (v_topic_id, 'pursue (v)', '/pərˈsuː/', 'đeo đuổi.', '(pursue sth) to do something or try to achieve something over a period of time.', 'Topic Vocabulary', 1, 51),
    (v_topic_id, 'recreation (n)', '/ˌriːkriˈeɪʃn/', 'sự tiêu khiển.', 'things that you do to enjoy yourself.', 'Topic Vocabulary', 1, 52),
    (v_topic_id, 'respite (n)', '/ˈrespɪt/', 'sự nghỉ ngơi, sự giải lao.', 'respite (from sth) a short break or escape from something difficult or unpleasant.', 'Topic Vocabulary', 1, 53),
    (v_topic_id, 'sedentary (adj)', '/ˈsednteri/', 'ngồi nhiều (về công việc).', '(of work, activities, etc.) in which you spend a lot of time sitting down.', 'Topic Vocabulary', 1, 54),
    (v_topic_id, 'socialise (v)', '/ˈsəʊʃəlaɪz/', 'hòa nhập xã hội.', 'to spend time with other people socially.', 'Topic Vocabulary', 1, 55),
    (v_topic_id, 'solitude (n)', '/ˈsɑːlətuːd/', 'tình trạng ở một mình, cuộc sống riêng của cá nhân.', 'the state of being alone, especially when you find this pleasant. SYNONYM: privacy', 'Topic Vocabulary', 1, 56),
